function metric(label,value,foot,icon='↗'){return `<div class="metric"><div class="row between"><span class="label">${label}</span><span class="symbol">${icon}</span></div><div class="value">${value}</div><div class="foot">${foot}</div></div>`}
function mineResults(){return db.results.filter(r=>studentsForView().some(s=>s.id===r.studentId))}
function lastResult(id){return db.results.filter(r=>r.studentId===id).sort((a,b)=>a.date.localeCompare(b.date)).at(-1)}
