function dashboard(){if(role==='teacher')return teacherDashboard();const s=getStudent(), rs=mineResults(), latest=studentsForView().map(s=>lastResult(s.id)).filter(Boolean), pending=db.homework.filter(h=>(!scoped()||h.grade===s?.grade)), average=avg(latest);const day=new Date().toLocaleDateString('tr-TR',{weekday:'long',timeZone:'Europe/Istanbul'}), lessons=db.sessions.filter(l=>(!scoped()||l.grade===s?.grade)&&l.day===day).sort((a,b)=>a.time.localeCompare(b.time));return header(role==='admin'?'Her gelişim, yeni bir başlangıç.':role==='teacher'?'Bugün de iz bırakalım.':role==='parent'?'Gelişimini birlikte izleyelim.':`Merhaba, ${esc(s?.name.split(' ')[0]||'öğrenci')} 👋`,'Öğrenmenin ritmini yakalayın. Bugünün planı ve tüm gelişmeler bir arada.',`<span class="calendarbox">▦ ${new Date().toLocaleDateString('tr-TR',{day:'numeric',month:'long',year:'numeric',timeZone:'Europe/Istanbul'})}</span>${!scoped()?'<button class="btn" onclick="examModal()">+ Sınav oluştur</button>':''}`)+`<section class="banner"><div><div class="eyebrow">HER ÖĞRENCİNİN YOLU FARKLI</div><h2>Küçük adımlar. Büyük gelişmeler.</h2><p>${scoped()?'Sınavlarını, ödevlerini ve çalışma planını tek yerden takip et. Hedefine giden bir sonraki adım burada.':'Öğrencilerinizi tanıyın, ihtiyaçlarını fark edin ve doğru zamanda destek olun. Eğitim yolculuğunun tamamı elinizin altında.'}</p><button class="link" style="padding:12px 0 0;color:#4b6d40" onclick="go('results')">Gelişim raporunu incele ↗</button></div><div class="bannerart" aria-hidden="true"><div class="paper">✓ GELİŞİM</div><span class="star">✦</span><div class="circlecheck">✓</div></div></section><div class="metrics">${metric(scoped()?'Sınıfım':'Aktif öğrenci',scoped()?esc(s?.grade||'—'):db.students.length,scoped()?'Eğitim yolculuğun devam ediyor':'9 farklı sınıf düzeyi desteklenir','♙')}${metric('Soru bankası',db.questions.filter(q=>!scoped()||q.grade===s?.grade).length,'Kazanım ve ders bazında sorular','▤')}${metric('Son sınav başarısı',latest.length?'%'+average:'—','Son tamamlanan sınavlara göre','↗')}${metric(scoped()?'Bekleyen ödev':'Yayınlanan sınav',scoped()?pending.filter(h=>!h.done.includes(s?.id)).length:db.exams.filter(e=>e.status!=='draft').length,scoped()?'Bir sonraki adımını planla':'Öğrencilere çözüm için açık','▣')}</div><div class="cols"><section class="card"><div class="cardhead"><div><h2>Gelişim, görünür olsun.</h2><p class="subtitle">Sınav tarihlerine göre başarı ortalaması</p></div><button class="link" onclick="go('results')">Tüm analizler ↗</button></div><div class="legend"><span><i class="dot"></i>Doğru cevap oranı</span><span>${live?'Sunucuda saklanan sonuçlar':'Örnek sonuçlar dahildir'}</span></div>${chart(rs)}</section><section class="card"><div class="cardhead"><h2>Bugünün ders akışı</h2><button class="link" onclick="go('schedule')">Haftalık plan ↗</button></div><span class="pill">${esc(day)}</span>${lessons.length?lessons.map(l=>`<div class="schedule-item"><span class="time">${l.time}</span><span class="schedule-line"></span><div><b>${esc(l.subject)}</b><p>${esc(l.grade)} · ${esc(l.teacher)}</p></div><span class="end">${l.duration} dk</span></div>`).join(''):empty('Bugün planlı ders yok','Haftalık programı inceleyebilirsiniz.')}</section></div><div class="cols"><section class="card"><div class="cardhead"><div><h2>${scoped()?'Son sınavlarım':'Öğrencilerden son durum'}</h2><p class="subtitle">Her sonuç, bir sonraki adım için ipucu.</p></div><button class="link" onclick="go('results')">Detaylar ↗</button></div>${scoped()?resultsTable(rs.slice(-4).reverse()):`<div class="tablewrap"><table><thead><tr><th>ÖĞRENCİ</th><th>SON BAŞARI</th><th>DURUM</th><th></th></tr></thead><tbody>${db.students.slice(0,4).map(s=>{const r=lastResult(s.id);return `<tr><td>${studentCell(s)}</td><td><div class="row">${r?r.percent+'%':'—'}<div class="miniprogress" style="width:70px"><span style="width:${r?.percent||0}%"></span></div></div></td><td>${pill(!r?'Sonuç bekleniyor':r.percent<60?'Destek zamanı':'İyi ilerliyor',r?.percent<60?'orange':'')}</td><td><button class="link" onclick="studentDetail('${s.id}')">↗</button></td></tr>`}).join('')}</tbody></table></div>`}</section><section class="card"><div class="cardhead"><h2>Kurumdan haberler</h2><button class="link" onclick="go('announcements')">Tümü ↗</button></div>${visibleAnnouncements().slice(0,2).map(a=>`<article class="announcement"><span class="pill orange">${esc(a.audience)}</span><h3 style="margin-top:10px">${esc(a.title)}</h3><p>${esc(a.body)}</p><small>${dateFmt(a.date)}</small></article>`).join('')}</section></div>`}
function students(){return header('Her öğrenciyi yakından tanıyın.','Sınıfları, gelişim durumunu ve veli bilgilerini tek yerden yönetin.',`<button class="btn" onclick="studentModal()">+ Öğrenci ekle</button>`)+`<div class="card"><div class="toolbar"><input id="search" placeholder="Öğrenci adı veya veli ara…" value="${esc(search)}" aria-label="Öğrenci ara"><select id="gradeFilter" aria-label="Sınıf filtresi">${options(grades,filterGrade,'Tüm sınıflar')}</select><button class="btn outline" onclick="exportStudents()">↓ CSV indir</button></div><div id="studentRows">${studentRows()}</div></div>`}
function studentRows(){const list=db.students.filter(s=>(!filterGrade||s.grade===filterGrade)&&`${s.name} ${s.parent}`.toLocaleLowerCase('tr').includes(search.toLocaleLowerCase('tr')));return `<div class="tablewrap"><table><thead><tr><th>ÖĞRENCİ</th><th>VELİ</th><th>SON BAŞARI</th><th>ÖDEV DURUMU</th><th>İŞLEM</th></tr></thead><tbody>${list.map(s=>{const r=lastResult(s.id),hw=db.homework.filter(h=>h.grade===s.grade);return `<tr><td>${studentCell(s)}</td><td>${esc(s.parent||'Belirtilmedi')}<div class="sub">${esc(s.phone||'Telefon eklenmedi')}</div></td><td>${r?pill('%'+r.percent,r.percent<60?'orange':''):'—'}</td><td>${hw.filter(h=>h.done.includes(s.id)).length} / ${hw.length} tamamlandı</td><td><button class="link" onclick="studentDetail('${s.id}')">Profil ↗</button> <button class="link" onclick="studentModal('${s.id}')">Düzenle</button></td></tr>`}).join('')}</tbody></table></div>${!list.length?empty('Eşleşen öğrenci bulunamadı','Filtreleri değiştirebilirsiniz.'):''}`}
function studentModal(id){const s=db.students.find(s=>s.id===id)||{},recordId=id||uid();modal(id?'Öğrenciyi düzenle':'Yeni öğrenci',`<form id="studentForm"><div class="formgrid">${field('Ad soyad','name','text',s.name||'','required maxlength="80"')}${selectField('Sınıf','grade',grades,s.grade||'8')}${field('Şube','section','text',s.section||'A','required maxlength="12"')}${field('Öğrencinin e-posta adresi','email','email',s.email||'','maxlength="254" autocomplete="email"')}${field('Veli adı soyadı','parent','text',s.parent||'','maxlength="80"')}${field('Veli telefonu','phone','tel',s.phone||'','maxlength="25"')}</div>${recordInviteField('student')}<div class="modalfoot"><button type="button" class="btn soft" onclick="closeModal()">Vazgeç</button><button class="btn" id="saveRecord">Kaydet</button></div></form>`);$('#studentForm').onsubmit=e=>savePerson(e,'students',recordId,id)}

function studentDetail(id){const s=db.students.find(s=>s.id===id),rs=db.results.filter(r=>r.studentId===id);modal(s.name,`<div class="row">${studentCell(s)}${pill('Veli: '+(s.parent||'Belirtilmedi'))}</div><div class="metrics" style="grid-template-columns:1fr 1fr">${metric('Son başarı',lastResult(id)?'%'+lastResult(id).percent:'—','Son tamamlanan sınav')}${metric('Sınav çözümü',rs.length,'Örnek sonuçlar dahildir')}</div>${chart(rs)}${resultsTable(rs.slice(-5).reverse())}`)}
function teachers(){return header('Birlikte öğretiyoruz.','Öğretmen kadrosunu ve branşları yönetin.',`<button class="btn" onclick="teacherModal()">+ Öğretmen ekle</button>`)+`<div class="grid3">${db.teachers.map(t=>`<div class="card"><div class="row">${teacherAvatar(t)}<div><h3>${esc(t.name)}</h3><p class="subtitle">${esc(t.subject)}</p></div></div><p class="subtitle" style="margin:22px 0">Haftalık ${db.sessions.filter(l=>l.teacher===t.name).length} planlı ders</p><button class="btn outline" onclick="teacherModal('${t.id}')">Bilgileri düzenle</button></div>`).join('')}</div>`}
function teacherModal(id){const t=db.teachers.find(x=>x.id===id)||{},recordId=id||uid();modal(id?'Öğretmen bilgileri':'Yeni öğretmen',`<form id="teacherForm" class="list">${field('Ad soyad','name','text',t.name||'','required maxlength="80"')}${selectField('Branş','subject',subjects,t.subject)}${field('E-posta adresi','email','email',t.email||'','maxlength="254" autocomplete="email"')}${recordInviteField('teacher')}<div class="modalfoot"><button type="button" class="btn soft" onclick="closeModal()">Vazgeç</button><button class="btn" id="saveRecord">Kaydet</button></div></form>`);$('#teacherForm').onsubmit=e=>savePerson(e,'teachers',recordId,id)}

function questions(){return header('Bilgi, iyi bir soruyla başlar.','Kazanım bazlı soru bankası. Tek tek ekleyin veya toplu içe aktarın.',`<button class="btn outline" onclick="bulkModal()">↑ Toplu soru yükle</button><button class="btn" onclick="questionModal()">+ Soru ekle</button>`)+`<div class="card"><div class="toolbar"><input id="search" placeholder="Soru metni veya kazanım ara…" value="${esc(search)}" aria-label="Soru ara"><select id="gradeFilter" aria-label="Sınıf filtresi">${options(grades,filterGrade,'Tüm sınıflar')}</select><select id="subjectFilter" aria-label="Ders filtresi">${options(subjects,questionSubject,'Tüm dersler')}</select></div><div id="questionRows">${questionRows()}</div></div>`}
function questionRows(){const qs=db.questions.filter(q=>(!filterGrade||q.grade===filterGrade)&&(!questionSubject||q.subject===questionSubject)&&`${q.text} ${q.topic}`.toLocaleLowerCase('tr').includes(search.toLocaleLowerCase('tr')));return `<div class="tiny">${qs.length} soru listeleniyor</div>${qs.slice(0,100).map((q,i)=>`<article class="question"><div class="row between"><div class="chips">${pill(q.grade==='Mezun'?'Mezun':q.grade+'. sınıf')}${pill(q.subject,'blue')}${pill(q.topic)}${pill(q.difficulty,'orange')}</div><div><button class="link" onclick="questionModal('${q.id}')">Düzenle</button><button class="link" onclick="deleteQuestion('${q.id}')">Sil</button></div></div><p><b>${i+1}.</b> ${esc(q.text)}</p>${q.image?`<img src="${esc(q.image)}" alt="Soru görseli">`:''}<div class="answers">${q.options.map((o,i)=>`<span class="${i===q.correct?'right':''}">${'ABCDE'[i]}) ${esc(o)} ${i===q.correct?'✓':''}</span>`).join('')}</div><div class="tiny" style="margin-top:8px">Çözüm: ${esc(q.explanation||'Çözüm açıklaması eklenmedi.')}</div></article>`).join('')||empty('Soru bulunamadı','Yeni bir soru ekleyin veya filtreyi değiştirin.')}`}
function questionModal(id){const q=db.questions.find(q=>q.id===id)||{};modal(id?'Soruyu düzenle':'Yeni soru',`<form id="questionForm"><div class="formgrid">${selectField('Sınıf','grade',grades,q.grade||'8')}${selectField('Ders','subject',subjects,q.subject)}${field('Kazanım / konu','topic','text',q.topic||'','required')}${selectField('Zorluk','difficulty',['Kolay','Orta','Zor'],q.difficulty||'Orta')}<label class="field full">Soru metni<textarea name="text" required>${esc(q.text||'')}</textarea></label>${[0,1,2,3,4].map(i=>field('ABCDE'[i]+' seçeneği'+(i===4?' (isteğe bağlı)':''),'op'+i,'text',q.options?.[i]||'',i<4?'required':'')).join('')}${selectField('Doğru cevap','correct',['A','B','C','D','E'],'ABCDE'[q.correct||0])}<label class="field full">Çözüm açıklaması<textarea name="explanation">${esc(q.explanation||'')}</textarea></label><label class="field full">Soru görseli (JPG / PNG / WebP, en fazla 500 KB)<input type="file" id="qImage" accept="image/png,image/jpeg,image/webp"></label>${q.image?'<label class="field full"><span><input name="removeImage" type="checkbox"> Mevcut görseli kaldır</span></label>':''}</div><div class="modalfoot"><button type="button" class="btn soft" onclick="closeModal()">Vazgeç</button><button class="btn">Soruyu kaydet</button></div></form>`);$('#questionForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target),d=Object.fromEntries(fd),op=[d.op0,d.op1,d.op2,d.op3,...(d.op4.trim()?[d.op4]:[])],correct='ABCDE'.indexOf(d.correct);if(correct>=op.length)return toast('Doğru cevap için E seçeneğini doldurun.');let image=d.removeImage?'':q.image||'',file=$('#qImage').files[0];if(file){if(file.size>500000||!['image/png','image/jpeg','image/webp'].includes(file.type))return toast('JPG, PNG veya WebP görseli en fazla 500 KB olabilir.');image=await readFile(file,'data')}const item={grade:d.grade,subject:d.subject,topic:d.topic,text:d.text,options:op,correct,explanation:d.explanation,difficulty:d.difficulty,image};if(id)Object.assign(q,item);else db.questions.push({id:uid(),...item});if(await save()){closeModal();render();toast('Soru kaydedildi.')}}}
async function deleteQuestion(id){if(db.exams.some(e=>e.questionIds.includes(id)))return toast('Bu soru bir sınavda kullanılıyor. Önce ilgili sınavı kaldırın.');if(confirm('Soru silinsin mi?')){db.questions=db.questions.filter(q=>q.id!==id);await save();render();toast('Soru silindi.')}}
function readFile(file,type='text'){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Dosya okunamadı. Dosyayı yeniden seçin.'));type==='data'?r.readAsDataURL(file):r.readAsText(file)})}
function parseCSV(s){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<s.length;i++){const c=s[i];if(c==='"'){if(quoted&&s[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(c===';'&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&s[i+1]==='\n')i++;row.push(cell);rows.push(row);row=[];cell=''}else cell+=c}if(quoted)throw Error('CSV içinde kapatılmamış tırnak var.');if(cell||row.length){row.push(cell);rows.push(row)}return rows}
let bulkContext=null,bulkBusy=false;
function bulkModal(inExam=false){importDraft=[];bulkBusy=false;bulkContext=inExam&&examDraft?{draft:examDraft,grade:examDraft.grade}:null;const context=bulkContext;modal(context?'Sınava toplu soru ekle':'Toplu soru yükle',`${context?`<button class="link" style="padding:0;margin-bottom:15px" onclick="cancelBulk()">← Sınava geri dön</button><div class="note"><b>${esc(gradeLabel(context.grade))}</b> için yükleme yapıyorsun. Dosyadaki sorular sınava otomatik seçilecek.</div>`:''}<div class="bulk-upload-steps"><section><h3><span>1</span> Örnek dosyayı indir ve doldur</h3><p>Her satıra bir soru, cevap seçenekleri ve doğru şıkkı yaz.</p><button class="btn outline" onclick="downloadTemplate()">↓ Örnek dosyayı indir (CSV)</button><details class="bulk-help"><summary>JSON dosyası kullanıyorum</summary><button class="link" onclick="downloadJSONTemplate()">JSON örneğini indir</button></details></section><section><h3><span>2</span> Hazırladığın dosyayı seç</h3><label class="field">CSV veya JSON dosyası<input type="file" id="bulkFile" accept=".csv,.json" aria-label="Soru dosyasını seç"></label><p>En fazla 1000 soru / 2 MB. PDF ve Word henüz desteklenmiyor.</p></section></div><div id="bulkPreview" class="bulk-preview" aria-live="polite"></div><div class="wizard-footer"><button class="btn soft" id="bulkCancel" onclick="cancelBulk()">${context?'← Sınava geri dön':'Vazgeç'}</button><button class="btn" id="importBtn" disabled onclick="commitQuestions()">${context?'Soruları sınava ekle':'Soruları kaydet'}</button></div>`);$('#modal').classList.add('exam-dialog');const input=$('#bulkFile');let readVersion=0;input.onchange=async()=>{const version=++readVersion,file=input.files[0];importDraft=[];$('#importBtn').disabled=true;$('#importBtn').textContent=context?'Soruları sınava ekle':'Soruları kaydet';$('#bulkPreview').textContent='';if(!file)return;if(file.size>2e6){$('#bulkPreview').textContent='Dosya 2 MB sınırını aşıyor. Daha küçük bir dosya seç.';return}$('#bulkPreview').textContent='Dosya kontrol ediliyor…';try{const raw=await readFile(file);if(version!==readVersion||!input.isConnected)return;importDraft=parseQuestionImport(raw,file.name,context?.grade);$('#bulkPreview').innerHTML=`<div class="bulk-ready"><b>✓ ${importDraft.length} soru hazır.</b><span>${context?'Aşağıdaki düğmeye basınca sınavına eklenecek.':'Kaydettiğinde soru bankasına eklenecek.'}</span></div><div class="bulk-preview-list">${importDraft.slice(0,3).map((q,i)=>`<p><b>${i+1}.</b> ${esc(q.subject)} · ${esc(q.text)}</p>`).join('')}${importDraft.length>3?`<p class="tiny">ve ${importDraft.length-3} soru daha…</p>`:''}</div>`;$('#importBtn').disabled=false;$('#importBtn').textContent=context?`${importDraft.length} soruyu sınava ekle`:`${importDraft.length} soruyu kaydet`}catch(err){if(version!==readVersion||!input.isConnected)return;importDraft=[];$('#bulkPreview').textContent=err.message;}}}
function parseQuestionImport(raw,filename,targetGrade){const ext=filename.split('.').at(-1).toLowerCase();if(!['csv','json'].includes(ext))throw Error('CSV veya JSON dosyası seç. PDF ve Word bu bölümde yüklenemez.');let rows;if(ext==='json'){rows=JSON.parse(raw.replace(/^\uFEFF/,''));if(!Array.isArray(rows))throw Error('JSON dosyası örnekteki gibi bir soru listesi olmalı.')}else{const all=parseCSV(raw.replace(/^\uFEFF/,'')),headings=all.shift()?.map(h=>h.trim());const required=['ders','soru','A','B','C','D','dogru',...(targetGrade?[]:['sinif'])];if(!headings||required.some(h=>!headings.includes(h))||new Set(headings).size!==headings.length)throw Error('Dosyanın sütunları uygun değil. Bu ekrandaki örnek dosyayı indirip doldur.');rows=all.filter(r=>r.some(c=>c.trim())).map(r=>Object.fromEntries(headings.map((h,i)=>[h,(r[i]||'').trim()]))).map(r=>({grade:r.sinif||targetGrade,subject:r.ders,topic:r.konu,text:r.soru,options:[r.A,r.B,r.C,r.D,...(r.E?[r.E]:[])],correct:'ABCDE'.indexOf(r.dogru.toUpperCase()),explanation:r.cozum,difficulty:r.zorluk||'Orta'}))}if(!rows.length||rows.length>1000)throw Error('Dosya 1 ile 1000 arasında soru içermeli.');const errors=[];rows.forEach((r,i)=>{const line=i+(ext==='csv'?2:1);if(!r||typeof r!=='object'){errors.push(`${line}. satır: soru bilgisi eksik.`);return}const g=String(r.grade||targetGrade||'');if(targetGrade&&g!==targetGrade){errors.push(`${line}. satır: ${gradeLabel(g)} sorusu var. Bu sınav ${gradeLabel(targetGrade)} için; dosyadaki sınıfı kontrol et.`);return}if(!grades.includes(g)||typeof r.subject!=='string'||!r.subject.trim()||typeof r.text!=='string'||!r.text.trim()||!Array.isArray(r.options)||r.options.length<4||r.options.length>5||r.options.some(o=>typeof o!=='string'||!o.trim())||!Number.isInteger(r.correct)||r.correct<0||r.correct>=r.options.length){errors.push(`${line}. satır: sınıf, ders, soru, seçenekler veya doğru cevap eksik / geçersiz.`);return}if(r.subject.length>120||r.text.length>6000||r.options.some(o=>o.length>2000)||String(r.topic||'').length>120||String(r.explanation||'').length>6000)errors.push(`${line}. satır: soru veya seçenek metni çok uzun.`)});if(errors.length)throw Error(errors.slice(0,5).join('\n'));return rows.map(r=>({id:uid(),grade:String(r.grade||targetGrade),subject:r.subject.trim(),topic:String(r.topic||'Genel').trim()||'Genel',text:r.text.trim(),options:r.options.map(x=>x.trim()),correct:r.correct,explanation:String(r.explanation||'').trim(),difficulty:['Kolay','Orta','Zor'].includes(r.difficulty)?r.difficulty:'Orta',image:''}))}
function cancelBulk(){if(bulkBusy)return;const context=bulkContext;bulkContext=null;importDraft=[];if(context&&examDraft===context.draft)examWizard();else closeModal()}
async function commitQuestions(){if(bulkBusy||!importDraft.length)return;const context=bulkContext,batch=[...importDraft],button=$('#importBtn'),previous=[...db.questions];bulkBusy=true;button.disabled=true;button.textContent='Sorular kaydediliyor…';$('#bulkFile').disabled=true;$('#bulkCancel').disabled=true;try{db.questions.push(...batch);await save();importDraft=[];bulkContext=null;render();if(context&&examDraft===context.draft&&examDraft.grade===context.grade){batch.forEach(q=>examDraft.ids.add(q.id));examDraft.query='';examDraft.importedCount=batch.length;examDraft.step=2;examWizard();toast(batch.length+' soru sınavına eklendi ve seçildi.')}else{closeModal();toast(batch.length+' soru bankaya eklendi.')}}catch(err){if(!live)db.questions=previous;toast(err.message);if(button.isConnected){button.disabled=false;button.textContent=context?`${batch.length} soruyu sınava ekle`:`${batch.length} soruyu kaydet`;$('#bulkFile').disabled=false;$('#bulkCancel').disabled=false}}finally{bulkBusy=false}}
function downloadTemplate(){const g=bulkContext?.grade;download('soru-yukleme-sablonu.csv','\uFEFF'+(g?'':'sinif;')+'ders;konu;soru;A;B;C;D;E;dogru;cozum;zorluk\n'+(g?'':'8;')+'Matematik;Üslü ifadeler;2³ kaçtır?;4;6;8;10;;C;2 × 2 × 2 = 8;Kolay','text/csv')}
function downloadJSONTemplate(){download('soru-yukleme-sablonu.json',JSON.stringify([{grade:bulkContext?.grade||'8',subject:'Matematik',topic:'Üslü ifadeler',text:'2³ kaçtır?',options:['4','6','8','10'],correct:2,explanation:'2 × 2 × 2 = 8',difficulty:'Kolay'}],null,2),'application/json')}

function exams(){if(quiz)return quizView();const s=getStudent(),visible=db.exams.filter(e=>!scoped()||(e.grade===s?.grade&&e.status!=='draft')),list=visible.filter(e=>scoped()||examTab==='all'||(examTab==='draft'?e.status==='draft':e.status!=='draft'));return header(scoped()?'Sıradaki adım: kendini dene.':'Sınavlarım',scoped()?'Sınavını aç, soruları çöz ve sonucunu gör.':'Taslaklarını tamamla, hazır sınavlarını öğrencilerine aç.',!scoped()?'<button class="btn" onclick="examModal()">+ Sınav oluştur</button>':'')+(!scoped()?`<div class="chips exam-tabs" aria-label="Sınav durumu">${[['all','Tümü'],['draft','Taslak'],['published','Yayında']].map(([key,label])=>`<button class="chip ${examTab===key?'active':''}" aria-pressed="${examTab===key}" onclick="examTab='${key}';renderPage()">${label} (${visible.filter(e=>key==='all'||(key==='draft'?e.status==='draft':e.status!=='draft')).length})</button>`).join('')}</div>`:'')+`<div class="list">${list.map(e=>{const draft=e.status==='draft',own=db.results.filter(r=>r.studentId===s?.id&&r.examId===e.id&&!r.sample);return `<article class="listcard"><div><div class="chips">${pill(gradeLabel(e.grade))}${pill(draft?'Taslak':'Yayında',draft?'orange':'blue')}</div><h3>${esc(e.title)}</h3><p>${e.questionIds.length} soru · ${e.duration} dakika${draft?' · Öğrencilere kapalı':own.length?' · '+own.length+' kez tamamlandı':''}</p></div><div class="row">${!scoped()?`<button class="btn ${draft?'dark':'soft'}" onclick="${draft?'examModal':'previewExam'}('${e.id}')">${draft?'Düzenle ve yayınla':'İncele'}</button><button class="link" onclick="removeExam('${e.id}')">${draft?'Sil':'Kaldır'}</button>`:role==='student'?`<button class="btn dark" onclick="startQuiz('${e.id}')">${own.length?'Tekrar çöz':'Sınava başla'} →</button>`:pill('Öğrenci panelinden çözülür')}</div></article>`}).join('')||empty(examTab==='draft'&&!scoped()?'Kaydedilmiş taslak yok.':'Henüz sınav yok.',scoped()?'Sınav yayınlandığında burada görünecek.':'“Sınav oluştur” ile başlayın.')}</div>`}

let examDraft=null,examTab='all';
const gradeLabel=g=>g==='Mezun'?'Mezun grubu':g+'. sınıf';
function examModal(id){const e=db.exams.find(x=>x.id===id&&x.status==='draft'),grade=e?.grade||db.students[0]?.grade||'8';examDraft={id:e?.id,created:e?.created,step:1,grade,title:e?.title||'',ids:new Set(e?.questionIds||[]),duration:e?.duration||0,penalty:e?.penalty||0,query:'',busy:false};examWizard()}

function wizardSteps(){return `<ol class="wizard-steps" aria-label="Sınav hazırlama adımları">${['Sınıfı seç','Soruları ekle','Yayınla'].map((label,i)=>`<li class="${examDraft.step===i+1?'current':examDraft.step>i+1?'complete':''}" ${examDraft.step===i+1?'aria-current="step"':''}><span>${examDraft.step>i+1?'✓':i+1}</span>${label}</li>`).join('')}</ol>`}
function examWizard(){if(!examDraft)return;const d=examDraft;d.ids=new Set([...d.ids].filter(id=>db.questions.some(q=>q.id===id&&q.grade===d.grade)));let body='';
if(d.step===1){body=`<div class="wizard-title"><h3>Sınıfını seç.</h3><p>Sınav bu sınıfın öğrencilerine açılır.</p></div><div class="grade-choices">${grades.map(g=>`<button type="button" class="grade-choice ${d.grade===g?'selected':''}" aria-pressed="${d.grade===g}" onclick="setExamGrade('${g}')"><b>${esc(gradeLabel(g))}</b><small>${db.questions.filter(q=>q.grade===g).length} hazır soru</small></button>`).join('')}</div><label class="field" style="margin-top:24px">Sınav adı <span class="tiny">İstersen değiştirebilirsin.</span><input id="wizardTitle" aria-label="Sınav adı" maxlength="120" value="${esc(d.title||examDefaultTitle())}"></label><div class="wizard-footer"><button class="btn soft" onclick="closeModal()">Vazgeç</button><button class="btn dark" id="wizardFirstNext">${actionLabel('Soruları ekle →','Devam →')}</button></div>`}
if(d.step===2){body=`<div class="wizard-title"><h3>Soruları ekle.</h3><p>${esc(gradeLabel(d.grade))} için soru yaz, dosya yükle veya aşağıdan seç.</p></div>${d.importedCount?`<div class="bulk-ready" style="margin-bottom:16px"><b>✓ ${d.importedCount} soru dosyadan eklendi.</b><span>Sınav için seçildi. İstersen seçimini değiştirebilirsin.</span></div>`:''}<div class="wizard-add-options"><button class="new-question-entry" onclick="examNewQuestion()"><span class="new-question-plus">+</span><span><b>Yeni soru yaz</b><small>Soru metnini, şıkları ve doğru cevabı gir.</small></span><span>→</span></button><button class="new-question-entry bulk-entry" onclick="bulkModal(true)"><span class="new-question-plus">↑</span><span><b>Toplu soru yükle</b><small>CSV veya JSON dosyasındaki soruları ekle.</small></span><span>→</span></button></div><div class="row between" style="margin:22px 0 12px"><h3>Hazır sorulardan seç</h3><button class="link" id="wizardSelectAll">Görünenlerin tümünü seç</button></div><input id="wizardQuestionSearch" class="wizard-search" aria-label="Hazır soru ara" placeholder="Soru veya ders ara…" value="${esc(d.query)}"><div id="wizardQuestionList" class="wizard-bank">${wizardQuestionList()}</div><div class="wizard-footer"><button class="btn soft" onclick="examWizardBack()">← Geri</button><div class="row"><span id="wizardSelectedCount" class="wizard-count" aria-live="polite">${d.ids.size} soru seçildi</span><button class="btn dark" id="wizardQuestionsNext" ${d.ids.size?'':'disabled'}>${actionLabel('Son adıma geç →','Devam →')}</button></div></div><p class="wizard-hint" id="wizardSelectionHint">${d.ids.size?'Seçtiğin sorular sınava eklenecek.':'Devam etmek için en az bir soru ekle.'}</p>`}
if(d.step===3){if(!d.duration)d.duration=Math.min(240,Math.max(5,d.ids.size*2));body=`<div class="wizard-title"><h3>Kontrol et ve yayınla.</h3><p>Süreyi seç. Hazırsan öğrencilerine aç.</p></div><div class="exam-summary"><span class="pill">${esc(gradeLabel(d.grade))}</span><h2>${esc(d.title||examDefaultTitle())}</h2><p><b>${d.ids.size} soru</b> seçildi · ${db.students.filter(s=>s.grade===d.grade).length} öğrenci bu sınıfa kayıtlı</p></div><div class="wizard-duration-field"><label for="wizardDuration">Öğrencilere kaç dakika süre verelim?</label><div class="row duration-presets">${[5,10,20,30,60].map(n=>`<button type="button" class="chip ${d.duration===n?'active':''}" aria-pressed="${d.duration===n}" onclick="examSetDuration(${n})">${n} dakika</button>`).join('')}</div><input id="wizardDuration" type="number" min="1" max="240" step="1" value="${d.duration}" aria-label="Sınav süresi (dakika)"></div><details class="wizard-advanced"><summary>Yanlış cevapların puana etkisi <span id="penaltySummary">${d.penalty?'Ceza açık':'Ceza yok'}</span></summary><p>Başlangıçta yanlışlar doğruları götürmez. Farklı bir sınav kuralı kullanıyorsan aşağıdan seçebilirsin.</p><label class="field">İstersen sınav kuralını değiştir<select id="wizardPenalty"><option value="0" ${d.penalty===0?'selected':''}>Yanlışlar doğruları götürmesin</option><option value="3" ${d.penalty===3?'selected':''}>3 yanlış, 1 doğruyu götürsün</option><option value="4" ${d.penalty===4?'selected':''}>4 yanlış, 1 doğruyu götürsün</option></select></label></details><div class="wizard-publish-note">✓ Yayınladığında bu sınıfa bağlı öğrenci hesaplarında görünecek.</div><div class="wizard-footer"><button class="btn soft" onclick="examWizardBack()">${actionLabel('← Sorulara dön','← Geri')}</button><button class="btn" id="wizardPublish">${actionLabel('Sınavı öğrencilere aç →','Yayınla')}</button></div>`}
modal('Sınav hazırla',`<div class="draft-save-row"><span class="tiny">${d.id?'Kaydedilmiş taslak':'Öğrencilere henüz açılmadı'}</span><button class="link" id="saveExamDraft" onclick="saveExamDraft()">Taslağı kaydet</button></div>`+wizardSteps()+body);$('#modal').classList.add('exam-dialog');
if(d.step===1){$('#wizardTitle').oninput=e=>d.title=e.target.value;$('#wizardFirstNext').onclick=()=>{d.title=$('#wizardTitle').value.trim()||examDefaultTitle();d.step=2;examWizard()}}
if(d.step===2){$('#wizardQuestionSearch').oninput=e=>{d.query=e.target.value;$('#wizardQuestionList').innerHTML=wizardQuestionList();bindWizardQuestions()};$('#wizardSelectAll').onclick=()=>{const qs=wizardFilteredQuestions();if(!qs.length)return;const all=qs.every(q=>d.ids.has(q.id));qs.forEach(q=>all?d.ids.delete(q.id):d.ids.add(q.id));$('#wizardQuestionList').innerHTML=wizardQuestionList();bindWizardQuestions();updateSelectionCount()};$('#wizardQuestionsNext').onclick=()=>{if(!d.ids.size)return;d.step=3;examWizard()};bindWizardQuestions();updateSelectionCount()}
if(d.step===3){$('#wizardDuration').oninput=e=>{d.duration=Number(e.target.value);$$('.duration-presets button').forEach(b=>{const selected=Number(b.textContent.split(' ')[0])===d.duration;b.classList.toggle('active',selected);b.setAttribute('aria-pressed',String(selected))})};$('#wizardPenalty').onchange=e=>{d.penalty=Number(e.target.value);$('#penaltySummary').textContent=d.penalty?'Ceza açık':'Ceza yok'};$('#wizardPublish').onclick=publishWizardExam}
}
function examDefaultTitle(){return gradeLabel(examDraft.grade)+' · '+dateFmt(today())+' Sınavı'}
function setExamGrade(g){const previous=examDefaultTitle();if(examDraft.grade!==g){examDraft.ids.clear();examDraft.importedCount=0;examDraft.duration=0;examDraft.grade=g;if(examDraft.title===previous)examDraft.title=''}examWizard()}
function examWizardBack(){if(examDraft.busy)return;examDraft.step=Math.max(1,examDraft.step-1);examWizard()}
function wizardFilteredQuestions(){const query=examDraft.query.toLocaleLowerCase('tr');return db.questions.filter(q=>q.grade===examDraft.grade&&(`${q.text} ${q.subject} ${q.topic}`).toLocaleLowerCase('tr').includes(query))}
function wizardQuestionList(){const qs=wizardFilteredQuestions();return qs.length?qs.map((q,i)=>`<label class="wizard-question ${examDraft.ids.has(q.id)?'picked':''}"><input type="checkbox" value="${q.id}" ${examDraft.ids.has(q.id)?'checked':''}><span><small>${esc(q.subject)} · ${esc(q.topic)}</small><b>${esc(q.text)}</b>${q.image?'<small>▧ Görselli soru</small>':''}</span><span class="picked-mark" aria-hidden="true">✓</span></label>`).join(''):empty(examDraft.query?'Aradığın soru bulunamadı.':'Bu sınıfa henüz soru eklenmedi.','“Yeni soru yaz” veya “Toplu soru yükle” ile başlayabilirsin.')}
function bindWizardQuestions(){$$('#wizardQuestionList input').forEach(el=>el.onchange=()=>{el.checked?examDraft.ids.add(el.value):examDraft.ids.delete(el.value);el.closest('label').classList.toggle('picked',el.checked);updateSelectionCount()})}
function updateSelectionCount(){if(!examDraft)return;const count=examDraft.ids.size;if($('#wizardSelectedCount'))$('#wizardSelectedCount').textContent=count+' soru seçildi';if($('#wizardQuestionsNext'))$('#wizardQuestionsNext').disabled=!count;if($('#wizardSelectionHint'))$('#wizardSelectionHint').textContent=count?'Seçtiğin sorular sınava eklenecek.':'Devam etmek için en az bir soru ekle.';if($('#wizardSelectAll')){const qs=wizardFilteredQuestions();$('#wizardSelectAll').disabled=!qs.length;$('#wizardSelectAll').textContent=qs.length&&qs.every(q=>examDraft.ids.has(q.id))?'Görünenlerin seçimini kaldır':'Görünenlerin tümünü seç'}}
function examSetDuration(n){examDraft.duration=n;examWizard()}
function examNewQuestion(){modal('Sınava yeni soru ekle',`<button class="link" style="padding:0;margin-bottom:20px" onclick="examWizard()">← Sorulara geri dön</button><span class="pill" style="float:right">${esc(gradeLabel(examDraft.grade))}</span><form id="wizardNewQuestion" class="list">${selectField('Bu soru hangi dersten?','subject',subjects,'Matematik')}<label class="field">Soruyu yaz<textarea name="text" required maxlength="6000" placeholder="Örn. 12 × 4 işleminin sonucu kaçtır?"></textarea></label><p class="tiny">Cevap seçeneklerini yaz. E seçeneği isteğe bağlıdır.</p><div class="formgrid">${[0,1,2,3,4].map(i=>field('ABCDE'[i]+' seçeneği'+(i===4?' (isteğe bağlı)':''),'op'+i,'text','',i<4?'required maxlength="2000"':'maxlength="2000"')).join('')}<label class="field">Doğru cevap hangisi?<select name="correct" aria-label="Doğru cevap hangisi?" required><option value="">Doğru şıkkı seç</option>${options(['A','B','C','D','E'])}</select></label></div><details class="wizard-advanced"><summary>Görsel, konu veya çözüm ekle <span>İsteğe bağlı</span></summary><div class="list" style="margin-top:16px">${field('Konu','topic','text','','placeholder="Örn. Çarpma işlemi" maxlength="120"')}<label class="field">Çözüm açıklaması<textarea name="explanation" maxlength="6000"></textarea></label><label class="field">Soru görseli (en fazla 500 KB)<input type="file" id="wizardQuestionImage" accept="image/png,image/jpeg,image/webp"></label></div></details><div class="wizard-footer"><button type="button" class="btn soft" onclick="examWizard()">Vazgeç</button><button class="btn" id="wizardSaveQuestion">Soruyu sınava ekle ✓</button></div><p class="wizard-hint">Bu soru, daha sonra kullanabilmen için soru bankasına da kaydedilir.</p></form>`);$('#modal').classList.add('exam-dialog');$('#wizardNewQuestion').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));const op=[0,1,2,3].map(i=>data['op'+i].trim());if(data.op4.trim())op.push(data.op4.trim());const correct='ABCDE'.indexOf(data.correct);if(!data.text.trim()||op.some(x=>!x)||correct<0||correct>=op.length)return toast('Soruyu, seçenekleri ve doğru cevabı kontrol et.');const button=$('#wizardSaveQuestion');button.disabled=true;button.textContent='Soru kaydediliyor…';try{let image='';const file=$('#wizardQuestionImage').files[0];if(file){if(file.size>500000||!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('Görsel JPG, PNG veya WebP biçiminde ve en fazla 500 KB olmalı.');image=await readFile(file,'data')}const q={id:uid(),grade:examDraft.grade,subject:data.subject,text:data.text.trim(),options:op,correct,topic:data.topic.trim()||'Genel',explanation:data.explanation.trim(),difficulty:'Orta',image};db.questions.push(q);await save();examDraft.ids.add(q.id);examDraft.query='';render();examWizard();toast('Soru sınava eklendi. İstersen başka soru da ekleyebilirsin.')}catch(err){toast(err.message);if(button.isConnected){button.disabled=false;button.textContent='Soruyu sınava ekle ✓'}}}}
async function publishWizardExam(){const d=examDraft;if(!d||d.busy)return;const duration=Number($('#wizardDuration').value);if(!Number.isInteger(duration)||duration<1||duration>240)return toast('Süreyi 1 ile 240 dakika arasında yaz.');const ids=[...d.ids];if(!ids.length||ids.some(id=>!db.questions.some(q=>q.id===id&&q.grade===d.grade))){d.step=2;examWizard();return toast('Sorular güncellenmiş. Seçimini tekrar kontrol et.')}d.busy=true;const button=$('#wizardPublish');button.disabled=true;button.textContent='Sınav yayınlanıyor…';const before=structuredClone(db);const exam={id:d.id||uid(),status:'published',title:d.title.trim()||examDefaultTitle(),grade:d.grade,duration,penalty:d.penalty,questionIds:ids,created:today()};try{const previous=db.exams.findIndex(e=>e.id===exam.id);if(previous>=0)db.exams[previous]=exam;else db.exams.push(exam);await save();closeModal();examTab='published';page='exams';render();modal('Sınav öğrencilerine açıldı',`<div class="exam-success"><span class="exam-success-check">✓</span><h2>${esc(exam.title)}</h2><p>${esc(gradeLabel(exam.grade))} · ${ids.length} soru · ${duration} dakika</p></div><div class="note">Bu sınıfa bağlı öğrenciler kendi hesaplarında <b>Sınavlar</b> bölümünden sınavı açabilir.</div><button class="btn dark" style="width:100%" onclick="closeModal()">Tamam, sınavlarıma dön</button>`);examDraft=null;toast('Sınav yayınlandı.')}catch(err){if(!live)db=before;d.busy=false;toast(err.message);if(button.isConnected){button.disabled=false;button.innerHTML=actionLabel('Sınavı öğrencilere aç →','Yayınla')}}}

function previewExam(id){const e=db.exams.find(e=>e.id===id);modal(e.title,`<p class="tiny">${e.grade} · ${e.duration} dakika · ${e.questionIds.length} soru</p>${e.questionIds.map((id,i)=>{const q=db.questions.find(q=>q.id===id);return q?`<div class="question"><b>${i+1}. ${esc(q.text)}</b><p class="tiny">${esc(q.options[q.correct])} ✓</p></div>`:''}).join('')}`)}
async function removeExam(id){if(!confirm(db.exams.find(e=>e.id===id)?.status==='draft'?'Bu taslak silinsin mi?':'Sınav yayından kaldırılsın mı? Eski sonuçlar korunur.'))return;db.exams=db.exams.filter(e=>e.id!==id);await save();render();toast('Sınav kaldırıldı.')}
async function startQuiz(id){if(live)return startLiveQuiz(id);const e=db.exams.find(e=>e.id===id);modal('Sınava hazır mısın?',`<h2>${esc(e.title)}</h2><p class="subtitle">${e.questionIds.length} soru · ${e.duration} dakika. Süre bittiğinde cevapların otomatik kaydedilir. İşaretlemediğin sorular boş sayılır.</p><div class="note" style="margin-top:18px">Bu pilotta ekran yenilenirse devam eden sınav kaybolur. Başlamadan önce bağlantını ve ayıracağın zamanı kontrol et.</div><div class="modalfoot"><button class="btn soft" onclick="closeModal()">Şimdi değil</button><button class="btn" id="confirmStart">Süreyi başlat</button></div>`);$('#confirmStart').onclick=()=>{quiz=id;qIndex=0;quizAnswers={};deadline=Date.now()+e.duration*60000;closeModal();render();clearInterval(timer);timer=setInterval(()=>{if(!quiz){clearInterval(timer);return}const remaining=Math.max(0,deadline-Date.now());if($('#quizTimer'))$('#quizTimer').textContent=clock(remaining);if(!remaining)finishQuiz(true)},1000)}}
const clock=ms=>String(Math.floor(ms/60000)).padStart(2,'0')+':'+String(Math.floor(ms/1000)%60).padStart(2,'0');
function quizView(){const e=db.exams.find(x=>x.id===quiz);if(!e){quiz=null;return exams()}const qs=e.questionIds.map(id=>db.questions.find(q=>q.id===id)).filter(Boolean),q=qs[qIndex];return `<section class="quiz">${header(esc(e.title),'Her soruda tek bir cevap seçin.',`<span class="pill orange" id="quizTimer">${clock(Math.max(0,deadline-Date.now()))}</span><button class="btn outline" onclick="exitQuiz()">Sınavdan çık</button>`)}<div class="card"><div class="row between"><span class="tiny">SORU ${qIndex+1} / ${qs.length}</span>${pill(q.subject+' · '+q.topic)}</div><p class="qtext">${esc(q.text)}</p>${q.image?`<img src="${esc(q.image)}" alt="Soru görseli">`:''}<div class="choices">${q.options.map((o,i)=>`<label class="choice"><input type="radio" name="quizAnswer" value="${i}" ${quizAnswers[q.id]===i?'checked':''} onchange="setQuizAnswer('${q.id}',${i})"><b>${'ABCDE'[i]}</b><span>${esc(o)}</span></label>`).join('')}</div><div class="row between quiz-navigation"><button class="btn soft" onclick="setQuizAnswer('${q.id}',null)">${actionLabel('Cevabı temizle','Temizle')}</button><div class="row"><button class="btn outline" ${qIndex===0?'disabled':''} onclick="qIndex--;renderPage()">← Önceki</button>${qIndex<qs.length-1?'<button class="btn dark" onclick="qIndex++;renderPage()">Sonraki →</button>':'<button class="btn" onclick="finishQuiz()">'+actionLabel('Sınavı bitir ✓','Bitir ✓')+'</button>'}</div></div></div><div class="card" style="margin-top:18px"><div class="row between" style="margin-bottom:15px"><h3>Soru haritası</h3><span class="tiny">${Object.keys(quizAnswers).length} / ${qs.length} cevaplandı</span></div><div class="row">${qs.map((q,i)=>`<button aria-label="${i+1}. soruya git" class="qnum ${quizAnswers[q.id]!==undefined?'done':''} ${qIndex===i?'active':''}" onclick="qIndex=${i};renderPage()">${i+1}</button>`).join('')}</div><button class="link" style="margin-top:15px" onclick="finishQuiz()">Sınavı şimdi tamamla →</button></div></section>`}
async function finishQuiz(auto=false){if(live)return finishLiveQuiz(auto);if(!quiz)return;const e=db.exams.find(x=>x.id===quiz),qs=e.questionIds.map(id=>db.questions.find(q=>q.id===id)).filter(Boolean);if(!auto&&!confirm(`${Object.keys(quizAnswers).length}/${qs.length} soru cevaplandı. Sınavı tamamlamak istiyor musun?`))return;const correct=qs.filter(q=>quizAnswers[q.id]===q.correct).length,blank=qs.filter(q=>quizAnswers[q.id]===undefined).length,wrong=qs.length-correct-blank;const r={id:uid(),studentId,examId:e.id,examTitle:e.title,date:today(),answers:{...quizAnswers},snapshot:structuredClone(qs),correct,wrong,blank,total:qs.length,net:correct-(e.penalty?wrong/e.penalty:0),percent:Math.round(correct/qs.length*100),sample:false};db.results.push(r);quiz=null;clearInterval(timer);await save();page='results';render();resultDetail(r.id);if(auto)toast('Süre doldu. Sınav otomatik kaydedildi.')}
async function exitQuiz(){if(live){quiz=null;clearInterval(timer);await refreshLive(false);render();toast('Cevaplar sunucuda saklandı. Sınavlar bölümünden devam edebilirsin.');return}if(confirm('Devam eden sınavdan çıkılsın mı? Bu sınavdaki cevaplar kaydedilmeyecek.')){quiz=null;clearInterval(timer);render()}}
function resultsTable(rs){return rs.length?`<div class="tablewrap"><table><thead><tr><th>ÖĞRENCİ / SINAV</th><th>D / Y / B</th><th>NET</th><th>BAŞARI</th><th></th></tr></thead><tbody>${rs.map(r=>{const s=db.students.find(s=>s.id===r.studentId);return `<tr><td><b>${esc(s?.name||'Silinen öğrenci')}</b><div class="sub">${esc(r.examTitle||db.exams.find(e=>e.id===r.examId)?.title||'Arşiv sınavı')} · ${dateFmt(r.date)} ${r.sample?'· örnek':''}</div></td><td>${r.correct} / ${r.wrong} / ${r.blank}</td><td>${Number(r.net).toLocaleString('tr-TR',{maximumFractionDigits:2})}</td><td>${pill('%'+r.percent,r.percent<60?'orange':'')}</td><td><button class="link" onclick="resultDetail('${r.id}')">Çözüm ↗</button></td></tr>`}).join('')}</tbody></table></div>`:empty('Henüz sınav sonucu yok','Öğrenci panelinden sınavı tamamlayarak rapor oluşturabilirsiniz.')}
function results(){const rs=mineResults().filter(r=>(!filterGrade||db.students.find(s=>s.id===r.studentId)?.grade===filterGrade)&&(!search||db.students.find(s=>s.id===r.studentId)?.name.toLocaleLowerCase('tr').includes(search.toLocaleLowerCase('tr'))));const latest=studentsForView().map(s=>lastResult(s.id)).filter(Boolean);return header('Sonuçların ötesine bakın.','Başarı yüzdesi, konu eksikleri ve ayrıntılı çözümler.',`<button class="btn outline" onclick="exportResults()">↓ Sonuçları indir</button>`)+`<div class="metrics">${metric('Sınav çözümü',rs.length,'Tekrar çözümler dahildir')}${metric('Ortalama başarı','%'+avg(rs),'Listelenen sınav sonuçları')}${metric('Son sınav ortalaması','%'+avg(latest),'Her öğrencinin son sınavı')}${metric('Destek gereksinimi',latest.filter(r=>r.percent<60).length,'Son başarı oranı %60 altında')}</div><div class="cols"><div class="card"><div class="cardhead"><h2>Başarı yolculuğu</h2>${pill('Doğru / toplam soru')}</div>${chart(rs)}</div><div class="card"><h2>Tekrar edilebilecek konular</h2><p class="subtitle">Cevap kayıtlarına göre yanlış + boş sayısı</p>${topicStats(rs)}</div></div><div class="card"><div class="toolbar">${!scoped()?`<input id="search" placeholder="Öğrenci ara…" value="${esc(search)}"><select id="gradeFilter">${options(grades,filterGrade,'Tüm sınıflar')}</select>`:''}<span class="tiny">${live?'Tamamlanan sınav sonuçları':'Örnek kayıtlar “örnek” olarak işaretlenmiştir.'}</span></div>${resultsTable(rs.slice().sort((a,b)=>b.date.localeCompare(a.date)))}</div>`}
function topicStats(rs){const stats={};rs.forEach(r=>{const qs=r.snapshot||db.exams.find(e=>e.id===r.examId)?.questionIds.map(id=>db.questions.find(q=>q.id===id)).filter(Boolean)||[];qs.forEach(q=>{if(r.answers[q.id]!==q.correct)stats[q.topic]=(stats[q.topic]||0)+1})});const list=Object.entries(stats).sort((a,b)=>b[1]-a[1]).slice(0,5),max=list[0]?.[1]||1;return list.length?list.map(([topic,n])=>`<div class="barrow"><span>${esc(topic)}</span><div class="miniprogress"><span style="width:${n/max*100}%;background:#dca47a"></span></div><b>${n}</b></div>`).join(''):empty('Konu eksiği görünmüyor','Sonuçlar arttıkça analiz ayrıntılanır.')}
function resultDetail(id){const r=db.results.find(r=>r.id===id),qs=r.snapshot||db.exams.find(e=>e.id===r.examId)?.questionIds.map(id=>db.questions.find(q=>q.id===id)).filter(Boolean)||[];modal('Sınav sonuç raporu',`<div class="center"><span class="pill">${esc(db.students.find(s=>s.id===r.studentId)?.name)}</span><div class="score">%${r.percent}</div><p class="tiny">${r.correct} doğru · ${r.wrong} yanlış · ${r.blank} boş · ${Number(r.net).toLocaleString('tr-TR',{maximumFractionDigits:2})} net</p><p class="tiny">${r.sample?'Örnek sonuç kaydı':'Tamamlanmış sınav'} · ${dateFmt(r.date)}</p></div>${qs.map((q,i)=>`<article class="question"><div class="row between"><span class="tiny">SORU ${i+1} · ${esc(q.topic)}</span>${pill(r.answers[q.id]===q.correct?'Doğru':r.answers[q.id]===undefined?'Boş':'Yanlış',r.answers[q.id]===q.correct?'':'orange')}</div><p>${esc(q.text)}</p><p class="tiny">Senin cevabın: ${r.answers[q.id]===undefined?'Boş':esc(q.options[r.answers[q.id]])}<br><b>Doğru cevap: ${esc(q.options[q.correct])}</b></p><div class="note" style="margin:10px 0 0">${esc(q.explanation||'Çözüm açıklaması eklenmedi.')}</div></article>`).join('')||empty('Sorular arşivden kaldırılmış','Sayısal sonuçlar korunmuştur.')}`)}
function homework(){const s=getStudent(),list=db.homework.filter(h=>!scoped()||h.grade===s?.grade);return header('Öğrenme, dersten sonra da sürer.','Ödevleri planlayın ve tamamlanma durumunu takip edin.',!scoped()?'<button class="btn" onclick="homeworkModal()">+ Ödev ata</button>':'')+`<div class="list">${list.map(h=>{const group=db.students.filter(s=>s.grade===h.grade),done=group.filter(s=>h.done.includes(s.id)).length;return `<article class="listcard"><div><div class="chips">${pill(h.grade==='Mezun'?'Mezun':h.grade+'. sınıf')}${pill(h.subject,'blue')}${pill('Son tarih: '+dateFmt(h.due),h.due<today()?'orange':'')}</div><h3>${esc(h.title)}</h3><p style="white-space:pre-wrap">${esc(h.description)}</p><p style="margin-top:9px">${scoped()?(h.done.includes(s?.id)?'✓ Tamamlandı':'Henüz tamamlanmadı'):`${done} / ${group.length} öğrenci tamamladı`}</p></div><div class="row">${role==='student'?`<button class="btn ${h.done.includes(s.id)?'soft':'dark'}" onclick="toggleHomework('${h.id}')">${h.done.includes(s.id)?'Tamamlandı ✓':'Tamamladım'}</button>`:!scoped()?`<button class="btn outline" onclick="homeworkDetail('${h.id}')">Teslim durumu</button><button class="link" onclick="removeHomework('${h.id}')">Sil</button>`:''}</div></article>`}).join('')||empty('Henüz ödev yok')}</div>`}
function homeworkModal(){modal('Yeni ödev ata',`<form id="homeworkForm"><div class="formgrid">${field('Ödev başlığı','title','text','','required')}${selectField('Sınıf','grade',grades,'8')}${selectField('Ders','subject',subjects)}${field('Son tarih','due','date',today(),'required')}<label class="field full">Yapılacak çalışma<textarea name="description" required placeholder="Kaynak, sayfa, soru aralığı ve yönerge…"></textarea></label></div><div class="modalfoot"><button class="btn">Ödevi yayınla</button></div></form>`);$('#homeworkForm').onsubmit=async e=>{e.preventDefault();db.homework.push({id:uid(),...Object.fromEntries(new FormData(e.target)),done:[]});await save();closeModal();page='homework';render();toast('Ödev sınıfa atandı.')}}
async function toggleHomework(id){const h=db.homework.find(h=>h.id===id);h.done=h.done.includes(studentId)?h.done.filter(s=>s!==studentId):[...h.done,studentId];await save();render();toast('Ödev durumu güncellendi.')}
function homeworkDetail(id){const h=db.homework.find(h=>h.id===id);modal(h.title,db.students.filter(s=>s.grade===h.grade).map(s=>`<div class="listcard" style="margin-bottom:8px">${studentCell(s)}${pill(h.done.includes(s.id)?'Tamamlandı':'Bekliyor',h.done.includes(s.id)?'':'orange')}</div>`).join('')||empty('Bu sınıfta öğrenci yok'))}
async function removeHomework(id){if(confirm('Ödev silinsin mi?')){db.homework=db.homework.filter(h=>h.id!==id);await save();render()}}
function schedule(){const days=['Pazartesi','Salı','Çarşamba','Perşembe','Cuma'];const list=db.sessions.filter(l=>(!scoped()||l.grade===getStudent()?.grade)&&(!filterGrade||l.grade===filterGrade));return header('Haftanın ritmini planlayın.','Dersler, öğretmenler ve derslikler. Tüm hafta bir bakışta.',!scoped()?'<button class="btn" onclick="sessionModal()">+ Ders ekle</button>':'')+`<div class="card"><div class="toolbar">${!scoped()?`<select id="gradeFilter" aria-label="Sınıf filtresi">${options(grades,filterGrade,'Tüm sınıflar')}</select>`:''}<span class="tiny">Tekrarlanan haftalık ders programı</span></div><div class="week">${days.map(d=>`<div class="day"><h3>${d}</h3>${list.filter(l=>l.day===d).sort((a,b)=>a.time.localeCompare(b.time)).map(l=>`<div class="slot"><span>${l.time} · ${l.duration} dk</span><strong>${esc(l.subject)}</strong>${esc(l.grade)} · ${esc(l.room)}<br>${esc(l.teacher)}${!scoped()?`<br><button class="link" onclick="removeSession('${l.id}')">Kaldır</button>`:''}</div>`).join('')||'<p class="tiny">Planlı ders yok</p>'}</div>`).join('')}</div></div>`}
function sessionModal(){modal('Haftalık programa ders ekle',`<form id="sessionForm"><div class="formgrid">${selectField('Gün','day',['Pazartesi','Salı','Çarşamba','Perşembe','Cuma'])}${field('Başlangıç','time','time','09:00','required')}${selectField('Sınıf','grade',grades,'8')}${selectField('Ders','subject',subjects)}${selectField('Öğretmen','teacher',db.teachers.map(t=>t.name))}${field('Derslik','room','text','Derslik 01','required')}${field('Süre (dakika)','duration','number',40,'min="15" max="180" required')}</div><div class="modalfoot"><button class="btn">Programa ekle</button></div></form>`);$('#sessionForm').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target)),start=minutes(d.time),end=start+Number(d.duration);const conflict=db.sessions.some(l=>l.day===d.day&&(l.teacher===d.teacher||l.room===d.room||l.grade===d.grade)&&start<minutes(l.time)+Number(l.duration)&&end>minutes(l.time));if(conflict)return toast('Bu saatte öğretmen, derslik veya sınıfın başka dersi var.');db.sessions.push({id:uid(),...d,duration:Number(d.duration)});await save();closeModal();page='schedule';render();toast('Ders programa eklendi.')}}
const minutes=s=>Number(s.split(':')[0])*60+Number(s.split(':')[1]);
async function removeSession(id){if(confirm('Ders haftalık programdan kaldırılsın mı?')){db.sessions=db.sessions.filter(l=>l.id!==id);await save();render()}}
let attDate=today();
function attendance(){if(role==='parent'){const s=getStudent(),records=Object.entries(db.attendance).filter(([key,v])=>v[s?.id]);return header('Devamlılık, gelişimin bir parçası.','Öğrencinizin günlük yoklama kayıtları.')+`<div class="card"><div class="tablewrap"><table><thead><tr><th>TARİH</th><th>ÖĞRENCİ</th><th>DURUM</th></tr></thead><tbody>${records.map(([d,r])=>`<tr><td>${dateFmt(d)}</td><td>${esc(s.name)}</td><td>${pill(r[s.id],r[s.id]==='Yok'?'orange':'')}</td></tr>`).join('')}</tbody></table></div>${!records.length?empty('Henüz yoklama kaydı yok'):''}</div>`}const list=db.students.filter(s=>!filterGrade||s.grade===filterGrade),saved=db.attendance[attDate]||{};return header('Kimler bugün aramızda?','Günlük devam durumunu sınıf bazında kaydedin.')+`<div class="card"><form id="attendanceForm"><div class="toolbar"><input type="date" id="attDate" value="${attDate}" required aria-label="Yoklama tarihi"><select id="gradeFilter" aria-label="Sınıf filtresi">${options(grades,filterGrade,'Tüm sınıflar')}</select><button type="button" class="btn outline" onclick="$$('.attStatus').forEach(s=>s.value='Var')">Tümü var</button><button class="btn">Yoklamayı kaydet</button></div><p class="tiny" style="margin-bottom:15px">Kayıtlar gün bazındadır. İşaretlenmeyen öğrenciler için yoklama kaydedilmez.</p><div class="tablewrap attendance"><table><thead><tr><th>ÖĞRENCİ</th><th>DEVAM DURUMU</th><th>KAYIT</th></tr></thead><tbody>${list.map(s=>`<tr><td>${studentCell(s)}</td><td><select class="attStatus" name="${s.id}" aria-label="${esc(s.name)} yoklama">${options(['İşaretlenmedi','Var','Yok','Geç','İzinli'],saved[s.id]||'İşaretlenmedi')}</select></td><td>${saved[s.id]?pill('Kaydedildi'):pill('Bekliyor','orange')}</td></tr>`).join('')}</tbody></table></div></form></div>`}
function coaching(){const list=db.plans.filter(p=>!scoped()||p.studentId===studentId);return header('Hedefe giden yol kişiye özel.','Öğrenciye özel çalışma adımları ve rehberlik planları.',!scoped()?'<button class="btn" onclick="planModal()">+ Çalışma adımı</button>':'')+`<div class="grid2">${list.map(p=>{const s=db.students.find(s=>s.id===p.studentId);return `<article class="card"><div class="row between">${pill(p.done?'Tamamlandı':'Devam ediyor',p.done?'':'orange')}<span class="tiny">${dateFmt(p.due)}</span></div><h3 style="margin:20px 0 12px">${esc(p.title)}</h3><p class="tiny">${esc(s?.name)}</p><div class="row" style="margin-top:23px">${role!=='parent'?`<button class="btn ${p.done?'soft':'dark'}" onclick="togglePlan('${p.id}')">${p.done?'Yeniden aç':'Tamamlandı işaretle'}</button>`:''}${!scoped()?`<button class="link" onclick="removePlan('${p.id}')">Sil</button>`:''}</div></article>`}).join('')||empty('Henüz kişisel çalışma planı yok')}</div>`}
function planModal(){if(!db.students.length)return toast('Önce öğrenci ekleyin.');modal('Kişisel çalışma adımı',`<form id="planForm" class="list"><label class="field">Öğrenci<select name="studentId">${db.students.map(s=>`<option value="${s.id}">${esc(s.name)} · ${esc(s.grade)}</option>`).join('')}</select></label>${field('Hedef / çalışma','title','text','','required')}${field('Tamamlanma tarihi','due','date',today(),'required')}<button class="btn">Plana ekle</button></form>`);$('#planForm').onsubmit=async e=>{e.preventDefault();db.plans.push({id:uid(),...Object.fromEntries(new FormData(e.target)),done:false});await save();closeModal();page='coaching';render();toast('Kişisel plan eklendi.')}}
async function togglePlan(id){const p=db.plans.find(p=>p.id===id);p.done=!p.done;await save();render()}
async function removePlan(id){if(confirm('Çalışma adımı silinsin mi?')){db.plans=db.plans.filter(p=>p.id!==id);await save();render()}}
function visibleAnnouncements(){return db.announcements.filter(a=>!scoped()||a.audience==='Tümü'||a.audience===roleNames[role]).slice().sort((a,b)=>b.date.localeCompare(a.date))}
function announcements(){return header('Herkes aynı sayfada olsun.','Kurum içi haberler, hatırlatmalar ve duyurular.',!scoped()?'<button class="btn" onclick="announcementModal()">+ Duyuru yayınla</button>':'')+`<div class="grid2">${visibleAnnouncements().map(a=>`<article class="card"><div class="row between">${pill(a.audience,'orange')}<span class="tiny">${dateFmt(a.date)}</span></div><h2 style="margin:20px 0 12px">${esc(a.title)}</h2><p class="subtitle" style="white-space:pre-wrap">${esc(a.body)}</p>${!scoped()?`<button class="link" style="margin-top:15px" onclick="removeAnnouncement('${a.id}')">Duyuruyu kaldır</button>`:''}</article>`).join('')||empty('Duyuru bulunmuyor')}</div>`}
function announcementModal(){modal('Yeni duyuru yayınla',`<form id="announcementForm" class="list">${field('Başlık','title','text','','required')}${selectField('Hedef kitle','audience',['Tümü','Öğrenci','Veli','Öğretmen'])}<label class="field">Duyuru metni<textarea name="body" required></textarea></label><button class="btn">Duyuruyu yayınla</button></form>`);$('#announcementForm').onsubmit=async e=>{e.preventDefault();db.announcements.unshift({id:uid(),...Object.fromEntries(new FormData(e.target)),date:today()});await save();closeModal();page='announcements';render();toast('Duyuru yayınlandı.')}}
async function removeAnnouncement(id){if(confirm('Duyuru kaldırılsın mı?')){db.announcements=db.announcements.filter(a=>a.id!==id);await save();render()}}
function finance(){const rows=db.payments.filter(p=>!scoped()||p.studentId===studentId),paid=rows.filter(p=>p.paid).reduce((s,p)=>s+p.amount,0),unpaid=rows.filter(p=>!p.paid).reduce((s,p)=>s+p.amount,0);return header('Eğitime odaklanın, kayıtlar düzenli kalsın.','Eğitim taksitleri ve tahsilat kayıtları. Bu bölüm ödeme almaz.',role==='admin'?'<button class="btn" onclick="paymentModal()">+ Taksit ekle</button>':'')+`<div class="metrics" style="grid-template-columns:repeat(3,1fr)">${metric('Toplam planlanan',money(paid+unpaid),'Tüm taksit kayıtları','₺')}${metric('Tahsil edildi',money(paid),'Elle kaydedilen tahsilatlar','✓')}${metric('Bekleyen',money(unpaid),'Henüz tahsil edilmedi','◷')}</div><div class="card"><div class="tablewrap"><table><thead><tr><th>ÖĞRENCİ</th><th>AÇIKLAMA</th><th>VADE</th><th>TUTAR</th><th>DURUM</th>${role==='admin'?'<th>İŞLEM</th>':''}</tr></thead><tbody>${rows.map(p=>`<tr><td><b>${esc(db.students.find(s=>s.id===p.studentId)?.name||'—')}</b></td><td>${esc(p.title)}</td><td>${dateFmt(p.due)}</td><td>${money(p.amount)}</td><td>${pill(p.paid?'Tahsil edildi':p.due<today()?'Gecikmiş':'Bekliyor',p.paid?'':p.due<today()?'red':'orange')}</td>${role==='admin'?`<td><button class="link" onclick="togglePayment('${p.id}')">${p.paid?'Geri al':'Tahsil edildi'}</button></td>`:''}</tr>`).join('')}</tbody></table></div>${!rows.length?empty('Taksit kaydı bulunmuyor'):''}</div>`}
function paymentModal(){if(!db.students.length)return toast('Önce öğrenci ekleyin.');modal('Eğitim taksiti ekle',`<form id="paymentForm"><div class="formgrid"><label class="field">Öğrenci<select name="studentId">${db.students.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></label>${field('Açıklama','title','text','','required')}${field('Tutar (TL)','amount','number','','min="1" step="0.01" required')}${field('Vade','due','date',today(),'required')}</div><div class="modalfoot"><button class="btn">Taksiti kaydet</button></div></form>`);$('#paymentForm').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));db.payments.push({id:uid(),...d,amount:Number(d.amount),paid:false});await save();closeModal();page='finance';render();toast('Taksit kaydedildi.')}}
async function togglePayment(id){const p=db.payments.find(p=>p.id===id);if(!confirm(p.paid?'Tahsilat kaydı geri alınsın mı?':'Bu taksit tahsil edildi olarak işaretlensin mi?'))return;p.paid=!p.paid;await save();render();toast('Tahsilat kaydı güncellendi.')}
function settings(){if(live)return liveSettings();return header('Kurumunuza göre şekillensin.','Kurum adı, veri yedekleme ve pilot sürüm bilgileri.')+`<div class="cols"><div class="card"><h2>Kurum bilgileri</h2>${institutionLogoEditor()}<form id="settingsForm" class="list" style="margin-top:22px">${field('Kurum adı','institution','text',db.institution,'required maxlength="60"')}<button class="btn" style="justify-self:start">Değişiklikleri kaydet</button></form><h2 style="margin-top:35px">Veri yedekleme</h2><p class="subtitle" style="margin-bottom:18px">Kayıtlar bu tarayıcıdadır. Yedeği indirerek başka bir cihaza taşıyabilirsiniz.</p><div class="row"><button class="btn outline" onclick="exportBackup()">↓ Yedeği indir</button><label class="btn soft" style="cursor:pointer">↑ Yedekten yükle<input type="file" id="backupFile" accept=".json" hidden></label></div><div class="note" style="margin:20px 0 0">Yedekten yükleme, bu tarayıcıdaki mevcut verilerin tamamını seçtiğiniz yedekle değiştirir.</div><button class="btn danger" style="margin-top:22px" onclick="resetDemo()">Örnek verilere dön</button></div><div class="card"><span class="pill">PİLOT SÜRÜM · 2.0</span><h2 style="margin-top:18px">Çalışan eğitim akışları</h2><p class="subtitle" style="line-height:2">✓ 5–12. sınıflar ve mezun grubu<br>✓ Öğrenci, öğretmen, veli, yönetim görünümleri<br>✓ CSV / JSON ile toplu soru yükleme<br>✓ Süreli sınav ve otomatik değerlendirme<br>✓ Ödev, yoklama ve kişisel çalışma planı<br>✓ Haftalık ders programı ve çakışma kontrolü<br>✓ Duyurular ve taksit kayıtları<br>✓ Veri yedekleme / geri yükleme</p><div class="note" style="margin:22px 0 0">Bu demo örnek verilerle çalışır ve kayıtları bu tarayıcıda saklar. Gerçek kurum kayıtlarınıza ulaşmak için “Gerçek hesabıma geç” düğmesini kullanın. Davetler kurum hesabından oluşturulur.</div></div></div>`}
function bindView(){if($('#search'))$('#search').oninput=e=>{search=e.target.value;if(page==='students')$('#studentRows').innerHTML=studentRows();else if(page==='questions')$('#questionRows').innerHTML=questionRows();else{const pos=e.target.selectionStart;renderPage();$('#search').focus();$('#search').setSelectionRange(pos,pos)}};if($('#gradeFilter'))$('#gradeFilter').onchange=e=>{filterGrade=e.target.value;renderPage()};if($('#subjectFilter'))$('#subjectFilter').onchange=e=>{questionSubject=e.target.value;$('#questionRows').innerHTML=questionRows()};if($('#attDate'))$('#attDate').onchange=e=>{attDate=e.target.value||today();renderPage()};if($('#attendanceForm'))$('#attendanceForm').onsubmit=async e=>{e.preventDefault();if(attDate>today())return toast('Gelecek tarih için yoklama kaydedilemez.');const data=db.attendance[attDate]||{};new FormData(e.target).forEach((v,k)=>{if(v==='İşaretlenmedi')delete data[k];else data[k]=v});db.attendance[attDate]=data;await save();render();toast('Günlük yoklama kaydedildi.')};if($('#settingsForm'))$('#settingsForm').onsubmit=async e=>{e.preventDefault();const name=new FormData(e.target).get('institution').trim();if(!name)return;db.institution=name;await save();render();toast('Kurum adı güncellendi.')};if($('#backupFile'))$('#backupFile').onchange=importBackup;}
function modal(title,body){$('#modal')._actionLayout=null;$('#modal').classList.remove('exam-dialog');$('#modal').innerHTML=`<div class="modalhead"><h2>${esc(title)}</h2><button class="close" aria-label="Kapat" onclick="closeModal()">×</button></div><div class="modalbody">${body}</div>`;if(!$('#modal').open)$('#modal').showModal();$('#modal').scrollTop=0;document.body.classList.add('modal-is-open');syncModalActions()}
function closeModal(){$('#modal').close()}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type:type+';charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
const csvCell=s=>'"'+String(s??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';
function exportStudents(){const rows=[['Ad soyad','Sınıf','Şube','Veli','Telefon'],...db.students.map(s=>[s.name,s.grade,s.section,s.parent,s.phone])];download('ogrenci-listesi.csv','\uFEFF'+rows.map(r=>r.map(csvCell).join(';')).join('\r\n'),'text/csv');toast('Öğrenci listesi indirildi.')}
function exportResults(){const rows=[['Öğrenci','Sınav','Tarih','Doğru','Yanlış','Boş','Net','Başarı %','Örnek'],...mineResults().map(r=>[db.students.find(s=>s.id===r.studentId)?.name,r.examTitle||db.exams.find(e=>e.id===r.examId)?.title,r.date,r.correct,r.wrong,r.blank,r.net,r.percent,r.sample?'Evet':'Hayır'])];download('sinav-sonuclari.csv','\uFEFF'+rows.map(r=>r.map(csvCell).join(';')).join('\r\n'),'text/csv');toast('Sonuçlar indirildi.')}
function exportBackup(){download('ftmotion-akademi-yedek-'+today()+'.json',JSON.stringify(db,null,2),'application/json');toast('Yedek indirildi.')}
function validateBackup(d){const arrays=['students','teachers','questions','exams','results','homework','sessions','announcements','payments','plans'];if(!d||d.schema!==2||typeof d.institution!=='string'||!d.institution.trim()||!d.attendance||typeof d.attendance!=='object'||Array.isArray(d.attendance)||arrays.some(k=>!Array.isArray(d[k])||d[k].length>20000))return false;for(const k of arrays){if(d[k].some(x=>!x||typeof x.id!=='string'||!/^[A-Za-z0-9_-]{1,100}$/.test(x.id))||new Set(d[k].map(x=>x.id)).size!==d[k].length)return false}const isText=x=>typeof x==='string',validDate=x=>isText(x)&&/^\d{4}-\d{2}-\d{2}$/.test(x);return d.students.length>0&&d.students.every(s=>isText(s.name)&&grades.includes(s.grade)&&isText(s.section)&&isText(s.parent)&&isText(s.phone))&&d.teachers.every(t=>isText(t.name)&&isText(t.subject))&&d.questions.every(q=>grades.includes(q.grade)&&isText(q.text)&&isText(q.subject)&&isText(q.topic)&&isText(q.explanation)&&Array.isArray(q.options)&&q.options.length>=4&&q.options.length<=5&&q.options.every(isText)&&Number.isInteger(q.correct)&&q.correct>=0&&q.correct<q.options.length&&(!q.image||/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(q.image)))&&d.exams.every(e=>isText(e.title)&&grades.includes(e.grade)&&Array.isArray(e.questionIds)&&e.questionIds.length>=(e.status==='draft'?0:1)&&[undefined,'draft','published'].includes(e.status)&&e.questionIds.every(id=>d.questions.some(q=>q.id===id&&q.grade===e.grade))&&e.duration>=1&&e.duration<=240&&[0,3,4].includes(e.penalty))&&d.results.every(r=>isText(r.studentId)&&isText(r.examId)&&validDate(r.date)&&Number.isFinite(r.percent)&&r.percent>=0&&r.percent<=100&&Number.isFinite(r.net)&&Number.isFinite(r.correct)&&Number.isFinite(r.wrong)&&Number.isFinite(r.blank)&&typeof r.answers==='object'&&r.answers!==null&&(!r.snapshot||(Array.isArray(r.snapshot)&&r.snapshot.every(q=>q&&typeof q.id==='string'&&/^[A-Za-z0-9_-]{1,100}$/.test(q.id)&&isText(q.text)&&isText(q.topic)&&Array.isArray(q.options)&&q.options.every(isText)&&Number.isInteger(q.correct)&&q.correct>=0&&q.correct<q.options.length))))&&d.homework.every(h=>isText(h.title)&&isText(h.description)&&grades.includes(h.grade)&&validDate(h.due)&&Array.isArray(h.done))&&d.sessions.every(l=>['Pazartesi','Salı','Çarşamba','Perşembe','Cuma'].includes(l.day)&&/^\d{2}:\d{2}$/.test(l.time)&&isText(l.subject)&&isText(l.teacher)&&isText(l.room)&&grades.includes(l.grade)&&Number.isFinite(l.duration))&&d.announcements.every(a=>isText(a.title)&&isText(a.body)&&validDate(a.date)&&['Tümü','Öğrenci','Veli','Öğretmen'].includes(a.audience))&&d.payments.every(p=>isText(p.studentId)&&isText(p.title)&&Number.isFinite(p.amount)&&p.amount>0&&validDate(p.due)&&typeof p.paid==='boolean')&&d.plans.every(p=>isText(p.studentId)&&isText(p.title)&&validDate(p.due)&&typeof p.done==='boolean')&&Object.values(d.attendance).every(x=>x&&typeof x==='object'&&Object.values(x).every(v=>['Var','Yok','Geç','İzinli'].includes(v)))}
async function importBackup(e){const f=e.target.files[0];if(!f)return;if(f.size>8e6)return toast('Yedek dosyası 8 MB sınırını aşıyor.');try{const d=JSON.parse(await readFile(f));if(!validateBackup(d))throw Error('Yedek biçimi geçersiz veya bu sürümle uyumsuz.');if(!confirm(`${d.students.length} öğrenci ve ${d.questions.length} soru içeren yedekle mevcut kayıtlar değiştirilsin mi?`))return;db=d;studentId=db.students[0]?.id||'';await save();render();toast('Yedek geri yüklendi.')}catch(err){toast(err.message)}finally{e.target.value=''}}
async function resetDemo(){if(!confirm('Bu tarayıcıda yaptığınız tüm değişiklikler silinip örnek veriler yüklensin mi? Önce yedek almanız önerilir.'))return;db=structuredClone(seed);studentId='s1';await save();render();toast('Örnek veriler yüklendi.')}
window.addEventListener('beforeunload',e=>{if(quiz){e.preventDefault();e.returnValue=''}});
function actionLabel(full,short){return `<span class="desktop-action-label">${full}</span><span class="mobile-action-label">${short}</span>`}
function syncMobileNavigation(){const mobile=window.matchMedia('(max-width:800px)').matches,side=$('#sidebar');if(!side)return;side.inert=mobile&&!menuOpen;const shell=$('.shell');if(shell)shell.inert=mobile&&menuOpen;side.classList.toggle('open',menuOpen);document.body.classList.toggle('menu-is-open',mobile&&menuOpen);const menu=$('.menu');if(menu)menu.setAttribute('aria-expanded',String(menuOpen));const backdrop=$('.mobile-menu-backdrop');if(backdrop)backdrop.hidden=!menuOpen}
function toggleMenu(open){menuOpen=Boolean(open);syncMobileNavigation();if(menuOpen)$('.mobile-nav-close')?.focus();else $('.menu')?.focus()}
function syncModalActions(){const dialog=$('#modal');if(!dialog?.open)return;const mobile=window.matchMedia('(max-width:800px)').matches,active=dialog._actionLayout;if(!mobile){if(active?.anchor.isConnected){active.anchor.replaceWith(active.footer);active.buttons.forEach(b=>b.removeAttribute('form'));active.bar.remove();dialog._actionLayout=null}return}if(active)return;const body=dialog.querySelector('.modalbody');let footer=body?.querySelector('.wizard-footer,.modalfoot');if(!footer){const primary=body?.querySelector('form>button.btn:last-child');if(primary){footer=document.createElement('div');footer.className='modalfoot';primary.before(footer);footer.append(primary)}}if(!footer)return;const form=footer.closest('form'),buttons=[];if(form){if(!form.id)form.id='modal-form-'+uid();footer.querySelectorAll('button').forEach(b=>{if(b.type==='submit'&&!b.hasAttribute('form')){b.setAttribute('form',form.id);buttons.push(b)}})}const anchor=document.createComment('modal action position');footer.before(anchor);const bar=document.createElement('div');bar.className='modal-actions';bar.setAttribute('aria-label','İşlem düğmeleri');bar.append(footer);dialog.append(bar);dialog._actionLayout={anchor,footer,bar,buttons}}
function updateVisibleViewport(){const viewport=window.visualViewport;if(viewport){document.documentElement.style.setProperty('--visible-height',viewport.height+'px');document.documentElement.style.setProperty('--visible-top',viewport.offsetTop+'px')}}
const mobileLayout=window.matchMedia('(max-width:800px)');mobileLayout.addEventListener('change',()=>{if(!mobileLayout.matches)menuOpen=false;syncMobileNavigation();syncModalActions()});window.visualViewport?.addEventListener('resize',updateVisibleViewport);window.visualViewport?.addEventListener('scroll',updateVisibleViewport);updateVisibleViewport();
$('#modal').addEventListener('close',()=>{document.body.classList.remove('modal-is-open');$('#modal')._actionLayout=null});

function teacherDashboard(){const drafts=db.exams.filter(e=>e.status==='draft'),published=db.exams.filter(e=>e.status!=='draft');return header('Bugün ne yapmak istersiniz?','Sınav, ödev ve sonuçlar tek yerde.')+`<div class="teacher-actions"><button class="card teacher-action" onclick="examModal()"><span class="teacher-action-icon">▣</span><h2>Sınav hazırla</h2><p>Sınıfı seç, soruları ekle, yayınla.</p><b>Başla →</b></button><button class="card teacher-action" onclick="homeworkModal()"><span class="teacher-action-icon">☑</span><h2>Ödev ver</h2><p>Yapılacak çalışmayı sınıfınla paylaş.</p><b>Ödev oluştur →</b></button><button class="card teacher-action" onclick="go('results')"><span class="teacher-action-icon">↗</span><h2>Sonuçları gör</h2><p>Öğrencilerin gelişimini takip et.</p><b>Sonuçlara git →</b></button></div><div class="cols"><section class="card"><div class="cardhead"><h2>Yarım kalan sınavlar</h2><button class="link" onclick="examTab='draft';go('exams')">Tüm taslaklar →</button></div>${drafts.length?drafts.slice(-3).reverse().map(e=>`<div class="teacher-draft"><div><b>${esc(e.title)}</b><p class="tiny">${esc(gradeLabel(e.grade))} · ${e.questionIds.length} soru</p></div><button class="btn soft" onclick="examModal('${e.id}')">Devam et</button></div>`).join(''):empty('Taslak sınav yok.','Yeni sınavını hazırlarken taslak olarak kaydedebilirsin.')}</section><section class="card"><h2>Çalışma alanım</h2><div class="list" style="margin-top:20px"><button class="institution-option" onclick="examTab='published';go('exams')"><span>Yayındaki sınavlar</span><b>${published.length} →</b></button><button class="institution-option" onclick="go('homework')"><span>Verilen ödevler</span><b>${db.homework.length} →</b></button><button class="institution-option" onclick="go('students')"><span>Öğrenciler</span><b>${db.students.length} →</b></button></div></section></div>`}
function recordInviteField(){return live&&role==='admin'?'<label class="record-invite"><input type="checkbox" name="createInvite" value="yes"> Bu e-posta için giriş daveti oluştur</label><p class="tiny">Davet seçilirse kayıtla birlikte kopyalanabilir bağlantı hazırlanır. E-posta gönderilmez.</p>':!live?'<p class="tiny">Demoda e-posta kaydedilir. Gerçek davet için kurum hesabınıza geçin.</p>':''}
async function savePerson(event,key,recordId,existingId){event.preventDefault();const form=event.target,button=$('#saveRecord'),before=structuredClone(db),d=Object.fromEntries(new FormData(form)),inviteRequested=d.createInvite==='yes';delete d.createInvite;d.name=d.name.trim();d.email=(d.email||'').trim().toLowerCase();if(!d.name)return;if(inviteRequested&&!d.email)return toast('Davet oluşturmak için e-posta adresini yazın.');button.disabled=true;button.textContent='Kaydediliyor…';try{const target=db[key].find(x=>x.id===existingId);if(target){if(key==='teachers')db.sessions.filter(l=>l.teacher===target.name).forEach(l=>l.teacher=d.name);Object.assign(target,d)}else db[key].push({id:recordId,...d});const invite=await save(inviteRequested?{email:d.email,role:key==='students'?'student':'teacher',studentId:key==='students'?recordId:null}:null);closeModal();render();if(invite&&invite.code)showInviteLink(invite);else toast('Kayıt kaydedildi.')}catch(err){if(!live)db=before;toast(err.message);if(button.isConnected){button.disabled=false;button.textContent='Kaydet'}}}
function showInviteLink(invite){const link=invitationUrl(invite);modal('Kayıt ve davet hazır',`<p><b>${esc(invite.email)}</b> · ${esc(roleNames[invite.role])}</p><p class="tiny">${new Date(invite.expires).toLocaleDateString('tr-TR')} tarihine kadar geçerli.</p><label class="field" style="margin:20px 0">Davet bağlantısı<input id="inviteLink" readonly value="${esc(link)}"></label><div class="modalfoot"><button class="btn soft" onclick="closeModal()">Tamam</button><button class="btn" onclick="copyInviteLink()">Bağlantıyı kopyala</button></div><div class="note">E-posta gönderilmedi. Bağlantıyı ilgili kişiyle paylaşın. Davet yalnızca bu e-posta hesabıyla kullanılabilir. Davet edilen e-posta doğrulanmış olmalıdır.</div>`)}
async function saveExamDraft(){const d=examDraft;if(!d||d.busy)return;d.busy=true;const before=structuredClone(db),button=$('#saveExamDraft');if(button){button.disabled=true;button.textContent='Kaydediliyor…'}try{if($('#wizardTitle'))d.title=$('#wizardTitle').value.trim();const duration=d.duration>0&&d.duration<=240&&Number.isInteger(d.duration)?d.duration:Math.min(240,Math.max(5,d.ids.size*2));const record={id:d.id||uid(),title:d.title.trim()||examDefaultTitle(),grade:d.grade,questionIds:[...d.ids],duration,penalty:d.penalty,status:'draft',created:d.created||today()};const index=db.exams.findIndex(e=>e.id===record.id);if(index>=0)db.exams[index]=record;else db.exams.push(record);await save();examDraft=null;closeModal();examTab='draft';page='exams';render();toast('Taslak kaydedildi. Öğrencilere açılmadı.')}catch(err){if(!live)db=before;d.busy=false;toast(err.message);if(button?.isConnected){button.disabled=false;button.textContent='Taslağı kaydet'}}}

function portalCards(){const roles=visiblePortalRoles();if(roles.length===1&&['admin','teacher'].includes(roles[0])){const c=portalDefinitions[roles[0]];return `<div class="portal-entry-card"><span aria-hidden="true">${c[0]}</span><div><b>${c[1]}</b><small>${c[2]}</small></div></div>`}return `<div class="portal-grid portal-family-grid">${roles.map(key=>{const c=portalDefinitions[key];return `<button class="portal-card ${portalRole===key?'selected':''}" onclick="selectPortal('${key}')" aria-pressed="${portalRole===key}"><span aria-hidden="true">${c[0]}</span><b>${c[1]}</b><small>${c[2]}</small></button>`}).join('')}</div>`}
function selectPortal(value){if(!visiblePortalRoles().includes(value))return;portalRole=value;const params=new URLSearchParams(location.search);params.delete('demo');params.set('giris',value);history.replaceState(null,'',educationHomeQuery(params));account?accountScreen():loginLanding()}
function loginLanding(){emailLoginLanding()}
function portalLinks(){const slug=live?.slug||account?.institutions.find(i=>i.tenant_id===tenantId)?.slug;return `<p class="tiny">Kişiler, davet edildikleri e-posta ile giriş yapar.</p><div class="portal-links">${Object.entries(roleNames).map(([key,name])=>`<a class="institution-option" href="/${esc(slug)}?giris=${key}"><span>${esc(name)} girişi</span><span>↗</span></a>`).join('')}</div>`}
function mediaState(){return live?.media||demoMedia}
function institutionLogo(){const src=mediaState().logo;return src?`<img class="institution-logo" src="${esc(src)}" alt="Kurum logosu">`:'<span class="school-placeholder" aria-hidden="true">▥</span>'}
function myPhoto(){return role==='teacher'?mediaState().profilePhoto||'':''}
function teacherAvatar(t){const src=live?mediaState().teachers?.[(t.email||'').toLowerCase()]:t.id===db.teachers[0]?.id?demoMedia.profilePhoto:'';return src?`<img class="avatar profile-avatar" src="${esc(src)}" alt="${esc(t.name)} fotoğrafı">`:initialsAvatar(t.name)}
function institutionLogoEditor(){return `<div class="institution-brand-editor">${institutionLogo()}<div><b>Kurum logosu</b><p class="tiny">Panellerinizde kurum adınızın yanında görünür.</p><button type="button" class="link" onclick="openMediaEditor('logo')">${mediaState().logo?'Logoyu değiştir':'Logo ekle'} →</button></div></div>`}
function profileModal(){modal('Profilim',`<div class="profile-summary">${myPhoto()?`<img class="profile-large" src="${esc(myPhoto())}" alt="Profil fotoğrafım">`:`<span class="profile-large profile-placeholder">${esc(initials(live?.user.name||(role==='teacher'?db.teachers[0]?.name||'Öğretmen':roleNames[role])))}</span>`}<h2>${esc(live?.user.name||(role==='teacher'?db.teachers[0]?.name||'Öğretmen':roleNames[role]))}</h2><p class="tiny">${esc(live?.user.email||'Örnek hesap')} · ${esc(roleNames[role])}</p></div>${role==='teacher'?'<button class="btn" style="width:100%" onclick="openMediaEditor(&quot;photo&quot;)">Profil fotoğrafımı düzenle</button>':''}${live?'<button class="btn outline" style="width:100%;margin-top:14px" onclick="installOnHome()">↓ Ana ekrana ekle</button><button class="btn outline" style="width:100%;margin-top:14px" onclick="closeModal();switchInstitution()">Kurumlarım</button><a class="btn outline" style="width:100%;margin-top:14px" href="/egitim-uygulama" onclick="emailSignOut(event)">Çıkış yap</a>':''}<div class="note" style="margin-top:20px">${esc(db.institution)} · Hesap yetkiniz kurum yönetimi tarafından belirlenir.</div>`)}
async function preparePhoto(file,kind){if(!file||!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('PNG, JPG veya WebP görsel seçin.');if(file.size>5*1024*1024)throw Error('Kaynak görsel en fazla 5 MB olmalı.');const source=await readFile(file,'data'),image=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(Error('Görsel okunamadı.'));img.src=source});if(image.width>12000||image.height>12000)throw Error('Görsel boyutları çok büyük.');const size=kind==='logo'?512:384,canvas=document.createElement('canvas');canvas.width=canvas.height=size;const ctx=canvas.getContext('2d');ctx.fillStyle='#ffffff';ctx.fillRect(0,0,size,size);const scale=kind==='logo'?Math.min((size*.84)/image.width,(size*.84)/image.height):Math.max(size/image.width,size/image.height),w=image.width*scale,h=image.height*scale;ctx.drawImage(image,(size-w)/2,(size-h)/2,w,h);const data=canvas.toDataURL(kind==='logo'?'image/png':'image/jpeg',.82);if(data.length>400000)throw Error('Görsel sıkıştırılamadı. Daha sade veya küçük bir görsel seçin.');return data}
function openMediaEditor(kind){if(kind==='logo'&&role!=='admin')return toast('Bu işlem kurum yöneticisine açık.');if(kind==='photo'&&role!=='teacher')return toast('Fotoğrafı öğretmen hesabından yükleyin.');const current=kind==='logo'?mediaState().logo:myPhoto();let pending='',busy=false;modal(kind==='logo'?'Kurum logosu':'Profil fotoğrafım',`<form id="mediaForm" class="list"><div class="media-preview"><img id="mediaPreview" src="${esc(current||'/egitim-uygulama/icons/academy-192.png')}" alt="Görsel önizlemesi" class="${kind==='photo'?'round':''}"></div><label class="field">${kind==='logo'?'Logo dosyası':'Fotoğraf dosyası'}<input type="file" id="profileImageFile" accept="image/png,image/jpeg,image/webp"></label><p class="tiny">PNG, JPG veya WebP · En fazla 5 MB. ${kind==='photo'?'Fotoğraf ortalanıp kareye kırpılır.':'Logo kare alana sığdırılır.'} Yüklemeden önce önizlemeyi kontrol edin.</p><p class="tiny" id="mediaStatus" role="status">${live?'Görsel kurumunuzun dosya alanına kaydedilir.':'Demoda yalnızca bu tarayıcıya kaydedilir.'}</p>${current?'<button type="button" class="link danger-text" id="removeProfileImage">Mevcut görseli kaldır</button>':''}<div class="modalfoot"><button type="button" class="btn soft" onclick="closeModal()">Vazgeç</button><button class="btn" id="saveProfileImage" disabled>Görseli kaydet</button></div></form>`);$('#profileImageFile').onchange=async event=>{const file=event.target.files[0],button=$('#saveProfileImage');button.disabled=true;pending='';if(!file)return;$('#mediaStatus').textContent='Önizleme hazırlanıyor…';try{pending=await preparePhoto(file,kind);$('#mediaPreview').src=pending;button.disabled=false;$('#mediaStatus').textContent='Önizleme hazır. Kaydettiğinizde kullanılacak.'}catch(err){$('#mediaStatus').textContent=err.message}};const persist=async(remove=false)=>{if(busy)return;if(!remove&&!pending)return;busy=true;$('#saveProfileImage').disabled=true;$('#profileImageFile').disabled=true;if($('#removeProfileImage'))$('#removeProfileImage').disabled=true;try{if(live){const result=await api('media',{kind,...(remove?{remove:true}:{data:pending})});live.media=result.media}else{if(kind==='logo')demoMedia.logo=remove?'':pending;else demoMedia.profilePhoto=remove?'':pending;localStorage.setItem('ftmotion-media-demo',JSON.stringify(demoMedia))}closeModal();render();toast(remove?'Görsel kaldırıldı.':'Görsel kaydedildi.')}catch(err){busy=false;$('#saveProfileImage').disabled=!pending;$('#profileImageFile').disabled=false;if($('#removeProfileImage'))$('#removeProfileImage').disabled=false;$('#mediaStatus').textContent=err.message}};$('#mediaForm').onsubmit=event=>{event.preventDefault();persist()};if($('#removeProfileImage'))$('#removeProfileImage').onclick=()=>{if(confirm('Bu görsel kaldırılsın mı?'))persist(true)}}
function standalone(){return window.matchMedia('(display-mode: standalone)').matches||(typeof navigator!=='undefined'&&navigator.standalone===true)}
function updatePwaMetadata(){if(!live)return;const link=$('#academyManifest'),href=EDUCATION_API+'manifest?slug='+encodeURIComponent(live.slug)+'&giris='+encodeURIComponent(role);if(link&&link.getAttribute('href')!==href){installPrompt=null;link.setAttribute('href',href)}document.title=db.institution+' · '+roleNames[role]}
function resetPwaMetadata(){const link=$('#academyManifest');if(link)link.setAttribute('href','/egitim-uygulama/manifest.webmanifest');installPrompt=null;document.title='FTMotion Akademi — Eğitim Yönetimi'}
async function installOnHome(){if(quiz)return toast('Önce devam eden sınavı tamamlayın.');if(!live)return toast('Önce kurum panelinize giriş yapın.');if(standalone())return toast('Paneliniz zaten uygulama penceresinde açık.');if(installPrompt){const prompt=installPrompt;installPrompt=null;await prompt.prompt();const result=await prompt.userChoice;if(result.outcome==='accepted')toast('Kurulum isteği onaylandı.');return}modal('Ana ekrana ekle',`<div class="install-preview">${institutionLogo()}<div><h2>${esc(db.institution)}</h2><p class="tiny">${esc(roleNames[role])} paneli</p></div></div><p class="tiny">Telefonunuzda simgeye dokunarak doğrudan bu kurumun panelini açabilirsiniz. Oturumunuz sona ererse yeniden giriş istenir.</p><ol class="install-instructions"><li><b>Android / Chrome:</b> Tarayıcının ⋮ menüsünü açın. “Uygulamayı yükle” veya “Ana ekrana ekle” seçeneğine dokunun.</li><li><b>iPhone / Safari:</b> Paylaş düğmesine, ardından “Ana Ekrana Ekle” seçeneğine dokunun.</li><li><b>Bilgisayar:</b> Chrome veya Edge adres çubuğundaki yükleme simgesini kullanın.</li></ol><div class="note">Yükleme seçeneği görünmüyorsa bağlantıyı Chrome veya Safari’de açın. Sınavlar ve güncel kayıtlar internet bağlantısı gerektirir.</div><div class="modalfoot"><button class="btn" onclick="closeModal()">Anladım</button></div>`)}
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event});window.addEventListener('appinstalled',()=>{installPrompt=null;toast('Uygulama ana ekrana eklendi.');if(live&&!quiz)render()});
if(typeof navigator!=='undefined'&&'serviceWorker' in navigator){const register=()=>navigator.serviceWorker.register('/sw.js',{scope:'/',updateViaCache:'none'}).catch(()=>{});if(document.readyState==='complete')register();else window.addEventListener('load',register,{once:true})}

initializeEducation();

async function api(path,data){return emailApi(path,data)}
function welcome(title,sub,body){$('#app').innerHTML=`<div class="welcome"><div class="welcome-brand"><span class="brandmark">F</span><b>FTMotion <span>AKADEMİ</span></b></div><main class="welcome-card"><div class="eyebrow">HER ÖĞRENCİNİN BİR SONRAKİ ADIMI İÇİN</div><h1>${title}</h1><p class="subtitle">${sub}</p><div style="margin-top:28px">${body}</div></main><p class="tiny center" style="margin-top:24px">${portalFooter()}</p></div>`}
async function boot(){clearInterval(timer);quiz=null;mode='loading';live=null;try{const params=new URLSearchParams(location.search);if(recoveryMode)return emailLoginLanding();if(params.get('demo')==='1')return enterDemo();welcome('Öğrenmenin ortak çalışma alanı.','Hesabınız ve kurumlarınız yükleniyor.','');account=await api('account');alignPortalWithMemberships();const invite=params.get('invite');if(invite)return claimScreen(invite);const target=requestedInstitution?.id||params.get('tenant')||tenantId|| (account.institutions.length===1?account.institutions[0].tenant_id:'');if(target&&account.institutions.some(x=>x.tenant_id===target&&(!portalRole||x.role===portalRole)))return await openInstitution(target);accountScreen()}catch(err){if(err.status===401)loginLanding();else welcome('Bağlantı henüz kurulamadı.',esc(err.message),'<button class="btn" onclick="boot()">Tekrar dene</button> <button class="btn outline" onclick="enterDemo()">Demoyu incele</button>')}}
function accountScreen(){live=null;mode='account';resetPwaMetadata();const institutions=account.institutions.filter(i=>!portalRole||i.role===portalRole),canCreate=canCreateInstitution();welcome(portalRole?roleNames[portalRole]+' girişi':`Merhaba, ${esc(account.user.name.split(' ')[0])}.`,portalRole?'Bu giriş türüne bağlı kurumunuzu seçin.':'Hangi alanda devam etmek istersiniz?',`${portalCards()}${institutions.length?`<div class="list" style="margin-top:22px">${institutions.map(i=>`<button class="institution-option" onclick="openInstitution('${i.tenant_id}')"><span><b>${esc(i.name)}</b><small>${esc(roleNames[i.role])}</small></span><span>↗</span></button>`).join('')}</div>`:`<div class="note" style="margin-top:22px">${portalRole?'Bu hesapta '+esc(roleNames[portalRole].toLocaleLowerCase('tr'))+' üyeliği bulunamadı. Kurumunuzun gönderdiği daveti, davetteki e-posta hesabıyla kabul edin.':'Henüz bir kuruma bağlı değilsiniz. Öğretmen, öğrenci ve veli hesapları yönetici davetiyle katılır.'}</div>`}${canCreate?`<form id="createInstitution" class="list" style="margin-top:25px">${field('Yeni kurum adı','name','text','','required minlength="2" maxlength="80" placeholder="Örn. FTMotion Pilot Kurs"')}<button class="btn">Kurum oluştur</button></form>`:''}<div class="row between" style="margin-top:28px"><button class="link" onclick="enterDemo()">Örnek demoyu incele</button><a class="link" href="/egitim-uygulama" onclick="emailSignOut(event)">Çıkış yap</a></div>`);if($('#createInstitution'))$('#createInstitution').onsubmit=async e=>{e.preventDefault();const btn=e.target.querySelector('button');btn.disabled=true;try{const r=await api('institutions',{name:new FormData(e.target).get('name')});account=await api('account');await openInstitution(r.tenantId)}catch(err){toast(err.message);btn.disabled=false}}}
async function openInstitution(id){tenantId=id;localStorage.setItem('ftmotion-tenant',id);await refreshLive(false);mode='live';portalRole=live.membership.role;page='dashboard';search='';filterGrade='';const slug=live.slug||account.institutions.find(i=>i.tenant_id===id)?.slug;history.replaceState(null,'','/'+slug);render();if(live.activeAttempt)resumeLiveAttempt(live.activeAttempt)}

async function refreshLive(show=true){if(quiz&&show)return toast('Sınav devam ederken ekran yenilenemez.');try{const r=await api('state');live=r;db=r.db;revision=r.revision;role=r.membership.role;studentId=r.membership.studentId||db.students[0]?.id||'';if(show){render();toast('Ortak kayıtlar güncellendi.')}}catch(err){if(show)toast(err.message);else throw err}}
function enterDemo(){live=null;mode='demo';quiz=null;clearInterval(timer);try{db=JSON.parse(localStorage.getItem('ftmotion-akademi-v2'))||structuredClone(seed)}catch{db=structuredClone(seed)}role=visiblePortalRoles().includes(portalRole)?portalRole:visiblePortalRoles()[0];studentId=db.students[0]?.id||'';page='dashboard';render()}
function prepareSignOut(){clearInterval(timer);tenantId='';localStorage.removeItem('ftmotion-tenant');live=null;account=null;mode='logout';quiz=null;menuOpen=false;try{closeModal()}catch{}resetPwaMetadata();}
async function switchInstitution(){if(quiz)return toast('Önce sınavı tamamlayın veya sınavdan çıkın.');try{const previousRole=live?.membership.role||portalRole;account=await api('account');requestedInstitution=null;tenantId='';localStorage.removeItem('ftmotion-tenant');portalRole=previousRole;alignPortalWithMemberships();history.replaceState(null,'',EDUCATION_ENTRY);accountScreen()}catch(err){toast(err.message)}}
function liveSettings(){return header('Kurumunuzun ortak çalışma alanı.','Kurum bilgileri, kullanıcı erişimleri ve sunucudaki kayıtlar.')+`<div class="cols"><section class="card"><h2>Kurum bilgileri</h2>${institutionLogoEditor()}<form id="settingsForm" class="list" style="margin-top:22px">${field('Kurum adı','institution','text',db.institution,'required maxlength="80"')}<button class="btn">Kurum adını kaydet</button></form><h2 style="margin-top:32px">Giriş bağlantıları</h2>${portalLinks()}<h2 style="margin-top:32px">Ekip ve erişim</h2><p class="subtitle" style="margin-bottom:20px">Öğretmen, öğrenci ve velileri e-posta adreslerine bağlı davetlerle kuruma ekleyin. Öğrenci ve veli hesapları yalnızca bağlı öğrencinin kayıtlarını görür.</p><button class="btn dark" onclick="membersModal()">Üyeleri ve davetleri yönet →</button><h2 style="margin-top:32px">Veri dışa aktarımı</h2><p class="subtitle" style="margin-bottom:16px">Kayıtlar ortak veritabanında saklanır. Yedeği ayrıca indirebilirsiniz. Canlı kayıtların toplu geri yüklemesi bu aşamada kapalıdır.</p><button class="btn outline" onclick="exportBackup()">↓ Kurum yedeğini indir</button></section><section class="card"><span class="pill">ORTAK VERİTABANI · v3.0</span><h2 style="margin:22px 0">Hesap ve yetki</h2><div class="list tiny"><p><b>Hesap:</b> ${esc(live.user.email)}</p><p><b>Yetki:</b> ${esc(roleNames[role])}</p><p>✓ Her kurum için ayrı kayıt alanı<br>✓ Her istekte sunucuda üyelik ve rol kontrolü<br>✓ Öğrenci sonuçları sunucuda hesaplanır<br>✓ Sınav cevapları kaydedilir ve sınava devam edilir<br>✓ Çakışan kayıtlar eski verinin üzerine yazmaz</p></div><div class="note" style="margin-top:25px">Davet bağlantısı kurumdaki rolü belirler. Davet edilen kişi, e-posta adresini doğrulayarak kuruma katılır.</div><a class="btn outline" href="/egitim-uygulama" onclick="emailSignOut(event)">Hesaptan çıkış yap</a></section></div>`}
async function membersModal(){try{const r=await api('members');modal('Kurum üyeleri ve davetler',`<div class="note">Davet bağlantıları 7 gün geçerlidir ve yalnızca belirtilen e-posta adresiyle kullanılabilir. E-posta gönderilmez; oluşan bağlantıyı kendiniz paylaşabilirsiniz.</div><h3>Üyeler</h3>${r.members.map(m=>`<div class="listcard" style="margin-top:10px"><div><b>${esc(m.name)}</b><p>${esc(m.email)} · ${esc(roleNames[m.role])}</p></div>${m.user_id!==r.ownerId?`<button class="link" onclick="revokeAccess('${m.id}','member')">Erişimi kaldır</button>`:pill('Kurum sahibi')}</div>`).join('')}<h3 style="margin:25px 0 12px">Bekleyen davetler</h3>${r.invitations.map(i=>`<div class="listcard" style="margin-top:10px"><div><b>${esc(i.email)}</b><p>${esc(roleNames[i.role])} · ${new Date(i.expires).toLocaleDateString('tr-TR')} tarihine kadar</p></div><button class="link" onclick="revokeAccess('${i.id}','invite')">İptal et</button></div>`).join('')||'<p class="tiny">Bekleyen davet yok.</p>'}<h3 style="margin:25px 0 15px">Yeni davet</h3><form id="inviteForm" class="list">${field('E-posta adresi','email','email','','required maxlength="254"')}<label class="field">Hesap türü<select name="role" id="inviteRole"><option value="teacher">Öğretmen</option><option value="student">Öğrenci</option><option value="parent">Veli</option></select></label><label class="field hidden" id="inviteStudentField">Bağlı öğrenci<select name="studentId">${db.students.map(s=>`<option value="${s.id}">${esc(s.name)} · ${esc(s.grade)}</option>`).join('')}</select></label><button class="btn">Davet bağlantısı oluştur</button></form>`);$('#inviteRole').onchange=e=>$('#inviteStudentField').classList.toggle('hidden',e.target.value==='teacher');$('#inviteForm').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(d.role!=='teacher'&&!d.studentId)return toast('Önce kurumda bir öğrenci kaydı oluşturun.');try{const r=await api('invite',d),link=invitationUrl({...r,role:d.role});modal('Davet bağlantısı hazır',`<p class="tiny">${esc(d.email)} · ${esc(roleNames[d.role])}<br>Geçerlilik: ${new Date(r.expires).toLocaleDateString('tr-TR')}</p><label class="field" style="margin:20px 0">Davet bağlantısı<input id="inviteLink" readonly value="${esc(link)}"></label><button class="btn" onclick="copyInviteLink()">Bağlantıyı kopyala</button><div class="note" style="margin-top:20px">Bağlantıyı yalnızca davet ettiğiniz kişiyle paylaşın. Davet edilen e-posta ile giriş yapın. Bağlantı e-posta ile gönderilmedi.</div>`)}catch(err){toast(err.message)}}}catch(err){toast(err.message)}}
async function copyInviteLink(){try{await navigator.clipboard.writeText($('#inviteLink').value);toast('Davet bağlantısı kopyalandı.')}catch{$('#inviteLink').select();toast('Bağlantıyı seçerek kopyalayabilirsiniz.')}}
async function revokeAccess(id,kind){if(!confirm(kind==='member'?'Bu kişinin kurum içi erişimi kaldırılsın mı?':'Davet bağlantısı iptal edilsin mi?'))return;try{await api('revoke',{id,kind});await membersModal();toast('Erişim kaydı güncellendi.')}catch(err){toast(err.message)}}
function claimScreen(code){welcome('Kurumunuza katılın.','Bu davet, yöneticinizin belirlediği hesap türüyle erişim verir.',`<div class="note">Giriş yapılan hesap: ${esc(account.user.email)}. Davetin e-posta adresi bu hesapla aynı olmalıdır.</div><button class="btn" id="claimInvite">Daveti kabul et →</button><button class="btn outline" style="margin-left:8px" onclick="history.replaceState(null,'',EDUCATION_ENTRY);accountScreen()">Kurumlarım</button>`);$('#claimInvite').onclick=async()=>{try{const r=await api('claim',{code});history.replaceState(null,'',EDUCATION_ENTRY);account=await api('account');await openInstitution(r.tenantId)}catch(err){toast(err.message)}}}
async function startLiveQuiz(id){if(live.activeAttempt){return resumeLiveAttempt(live.activeAttempt)}const e=db.exams.find(e=>e.id===id);modal('Sınava hazır mısın?',`<h2>${esc(e.title)}</h2><p class="subtitle">${e.questionIds.length} soru · ${e.duration} dakika. Süre sunucuda başlatılır. Cevapların her seçimde kaydedilir; sayfayı yenilersen kaldığın yerden devam edebilirsin.</p><div class="modalfoot"><button class="btn soft" onclick="closeModal()">Şimdi değil</button><button class="btn" id="liveStart">Süreyi başlat</button></div>`);$('#liveStart').onclick=async()=>{try{$('#liveStart').disabled=true;const r=await api('attempt',{examId:id});closeModal();resumeLiveAttempt(r.attempt)}catch(err){toast(err.message);if($('#liveStart'))$('#liveStart').disabled=false}}}
function resumeLiveAttempt(a){live.activeAttempt=a;if(a.questions){const qs=JSON.parse(a.questions);for(const q of qs){const i=db.questions.findIndex(x=>x.id===q.id);if(i>=0)db.questions[i]=q;else db.questions.push(q)}if(!db.exams.some(e=>e.id===a.exam_id))db.exams.push({id:a.exam_id,title:a.title||'Devam eden sınav',grade:getStudent().grade,questionIds:qs.map(q=>q.id),duration:0,penalty:a.penalty||0})}quiz=a.exam_id;deadline=a.expires;quizAnswers=JSON.parse(a.answers||'{}');qIndex=0;page='exams';render();clearInterval(timer);timer=setInterval(()=>{if(!quiz)return clearInterval(timer);const left=Math.max(0,deadline-Date.now());if($('#quizTimer'))$('#quizTimer').textContent=clock(left);if(!left){clearInterval(timer);finishLiveQuiz(true)}},1000);if(deadline<=Date.now()){clearInterval(timer);finishLiveQuiz(true)}}
function setQuizAnswer(id,answer){if(!live){if(answer===null)delete quizAnswers[id];else quizAnswers[id]=answer;return renderPage()}if(Date.now()>=deadline)return finishLiveQuiz(true);const prev=quizAnswers[id];if(answer===null)delete quizAnswers[id];else quizAnswers[id]=answer;renderPage();answerQueue=answerQueue.then(async()=>{answerBusy=true;try{await api('answer',{attemptId:live.activeAttempt.id,questionId:id,answer});live.activeAttempt.answers=JSON.stringify(quizAnswers)}catch(err){if(prev===undefined)delete quizAnswers[id];else quizAnswers[id]=prev;toast('Cevap kaydedilemedi: '+err.message);if(quiz)renderPage();throw err}finally{answerBusy=false}}).catch(()=>{});}
async function finishLiveQuiz(auto=false){if(!quiz||finishLiveQuiz.busy)return;if(!auto&&!confirm('Sınavı tamamlayıp sonuçlarını görmek istiyor musun?'))return;finishLiveQuiz.busy=true;try{await answerQueue;const r=await api('finish',{attemptId:live.activeAttempt.id});quiz=null;clearInterval(timer);db=r.db;revision=r.revision;live.activeAttempt=null;page='results';render();resultDetail(r.resultId);if(auto)toast('Süre doldu. Kaydedilen cevapların değerlendirildi.')}catch(err){toast(err.message)}finally{finishLiveQuiz.busy=false}}
window.addEventListener('unhandledrejection',e=>{e.preventDefault();toast(e.reason?.message||'İşlem tamamlanamadı.')});
setInterval(()=>{if(mode==='live'&&!quiz&&!$('#modal').open&&!document.hidden)refreshLive(false).then(()=>renderPage()).catch(()=>{})},30000);
